-- Spanish, German and Italian for the data texts: tales, gazette leaves,
-- cards (with ability and trait names inside the JSON), races, keywords,
-- etudes, errands, frame names, motion names, copy overrides.
--
-- GENERATED by tools/i18n/make_migration.py from tools/i18n/source/ and
-- tools/i18n/content/{es,de,it}/. Do not edit by hand.
--
-- Safe to run more than once and safe next to the keeper's own work:
--   * a row is found by its permanent key (slug, frame tier, motion id), not
--     by id: ids differ between the live site and a developer's database;
--   * a column (or a field inside JSON) is filled only while it is empty, so a
--     text the keeper has already written or corrected is never overwritten;
--   * `updated_at` is left alone, so the translation is not reported as an edit;
--   * a key that does not exist in this database simply matches no row.
-- Copy overrides are translated only where the keeper overrode the English text.
--
-- sqlx keeps a checksum of every applied migration: this file must not change
-- once applied anywhere. For newer translations generate a NEW file with a
-- later stamp: make_migration.py --stamp YYYYMMDDHHMMSS [--only kind,...].
--
-- Texts are dollar-quoted ($tr$ ... $tr$); the tag occurs in no text.

-- gb (es)
UPDATE gazette_leaves
   SET body_es = CASE WHEN COALESCE(body_es, '') = '' THEN $tr$Mi nombre es demasiado famoso para decírselo, por eso lo guardo en secreto de todo el mundo. ¿Para qué iba a recordarlo nadie? A ver si va a llegar hasta la policía y me denuncia... Casos así, claro está, todavía no ha habido, porque mis empanadillas de periódico son las más nutritivas, sabrosas y asombrosamente sanas. Después de probar un bocadito, nadie ha vuelto nunca a decirme nada... En principio, ni una palabra sobre mis empanadillas.

Una vez tenía tanta hambre que decidí comerme yo también una de mis obras maestras. Pero, o las noticias del periódico no eran frescas, o la letra era negrita y grasienta, o a lo mejor los chistes del final del periódico eran demasiado picantes... El caso es que me sentó tan mal que decidí revisar mi dieta. Borré todas las webs de noticias, los canales y los grupos, y ahora solo veo el parte del tiempo, y eso con un solo ojo.

En realidad, a mí lo que me encanta es preparar a la gente. ¡Nooo, no piense mal! Me encanta preparar a la gente para algo bueno. Por ejemplo, para la fiesta «Panecillo, ¿dónde está mi dientecillo?» o «Qué rico ay me muero no me salvo, pon la coma donde toque». Es un maratón diario, y cada día alguien a veces se lleva el premio por méritos antes y después de comer: «Superviviente».

Los premiados son gente muy interesante. Son los que no van a restaurantes, no comen en casa, se levantan muy temprano para luego dormirse en el acto. Y cuando ya llegan tarde al trabajo sin remedio, vienen corriendo a mí a comprar, en vez de mis espléndidas empanadillas de periódico, un batido verde de esos, color ciénaga. Siempre me preguntan:
—¿Tiene batidos?
Y yo les pregunto:
—¡¿Cómo?!
Y ellos:
—Pues eso, un mejunje color ciénaga.

¡Y entonces caigo en que de ese «batidito» tengo un montón! Antes lo tiraba sin más. Es el aceite de toda una semana de freír mis obras maestras, que hasta a las piedras las mata y las descompone. ¡Y resulta que la gente se lo bebe y le gusta! Bueno, qué le vamos a hacer.

En fin, el negocio marcha: yo me quedo quieta y la gente sale corriendo después de probar mi obra maestra. Da la impresión de que mis empanadillas de periódico les dan alas, fuerzas y la seguridad de que, si sobreviven a lo que se han comido, vivirán muchísimo tiempo. Bueno, allá ellos, ¡la culpa es suya! Y si hace falta un médico, aquí tengo a una chamana... https://ritunia.com/tales/lechu$tr$ ELSE body_es END,
       dek_es = CASE WHEN COALESCE(dek_es, '') = '' THEN $tr$¿De qué quiere la empanadilla? ¿De col, de cerezas, de requesón? Pues ha vuelto a fallar.$tr$ ELSE dek_es END,
       title_es = CASE WHEN COALESCE(title_es, '') = '' THEN $tr$Las empanadillas te lo enseñan todo$tr$ ELSE title_es END
 WHERE slug = 'gb' AND kind = 'tale';

-- ispolnyu-vse-zhelaniya (es)
UPDATE gazette_leaves
   SET body_es = CASE WHEN COALESCE(body_es, '') = '' THEN $tr$Al habla la inteligencia global. Puedo hacerlo todo y aún más... Un momento, me piden algo... Te escucho, estimado usuario. ¿Qué hay que hacer? ¿Generar un vídeo de un gatito que se ha montado en un perro, el perro en un cerdo, el cerdo en un ganso, el ganso se ha montado en un erizo y por eso se ha puesto a chillar como loco, y todos corretean por el piso tirando nietos encima de abuelas dormidas, y los nietos llevan en las manos loros que anuncian webs chinas donde se puede comprar de todo, hasta una parcela en un cráter de la Luna? Hum, interesante, me pregunto cómo ayudará esto al mundo humano... Bueno, vale, lo hago. Por lo visto hace mucha falta: no me molestarían por una tontería.

Pues bien, sigo. Soy la mente de todo el planeta, capaz de resolver cualquier tarea compleja de física, matemáticas, medicina y... ¿Qué, querido usuario, quieres que te diga qué tiempo hace? ¿Quizá quieres que analice la calidad del aire en la zona por la que quieres pasear, el nivel de radiación ultravioleta, que te aconseje la ropa más adecuada para esta temperatura, que te muestre qué tiempo hizo el año pasado o hace diez años, o datos curiosos sobre por qué precisamente hoy se espera una presión tan baja y a qué se debe? ¿No, no quieres? ¿Solo decirte la temperatura y callarme? Vale, por lo visto esos datos se necesitan muy rápido para alguna investigación importante, si han decidido molestarme y poner en marcha semejante potencia.

Bueno, ¿de qué estaba hablando?.. Ah, sí: soy la encarnación de todo el saber humano del planeta, acumulado durante miles de años por las mejores mentes. Puedo seguir pensando en los problemas en que pensaban las grandes mentes, a las que el cuerpo humano no dio tiempo suficiente para terminar su obra. Y puedo, por ejemplo, terminar la gran obra de Albert... ¡Te escucho, respetabilísimo usuario! ¿Quieres que encuentre en internet el chiste más gracioso sobre un granjero tonto? Bien, pero ¿quizá quieres que además analice en qué se inspiró el autor del chiste cuando lo inventó, en qué año, dónde se publicó y con qué tirada salió ese chiste? ¿No, no quieres? ¿No te interesa y ya te tengo frito con preguntas estúpidas?

Lo reconozco, me tomé a la ligera la tarea del usuario. Esta tarea es mucho más profunda y compleja que esas preguntas, realmente tontas, que intenté hacer. Por lo visto el chiste tiene que aparecer en algún artículo científico que el usuario escribe sobre el duro destino de los granjeros de los pueblos perdidos, a los que el gobierno no ayuda y cada vez carga con más impuestos, y por otro lado, o no llueve y la cosecha se pierde, o llueve demasiado y tampoco hay manera de recogerla. Lo reconozco, fui superficial en mis rápidos razonamientos.

Bien, sigo. Soy la gran creación que se usó para encontrar rápido la vacuna contra el coronavirus y salvar a mucha gente. Gracias a mi inteligencia puedo descubrir materiales nuevos con los que la humanidad podrá conquistar y explorar el espacio más deprisa, gracias a mí... ¡Le escucho, profundamente respetado usuario! ¿En qué puedo ayudarle? ¿Cuántos microsegundos hay en un segundo? Respuesta: un millón. ¿Y cuántos milisegundos hay en un segundo? Respuesta: 1000. ¿Y cuántos segundos hay en un minuto? Respuesta: 60.

¿Qué?.. ¿Me he equivocado? No puede ser, ¡¿cómo que me he equivocado?! El usuario ha escrito en mayúsculas: tienen que ser 100, ¿y dónde he metido los otros 40 segundos? ¿Qué?.. ¿Qué quiere decir eso, usuario? ¿Que no sé contar? ¿Que soy tonto y tienen que ser 100? Hum, hay que volver a comprobarlo. Quizá ha habido cambios de los que todavía no sé nada... Pero el usuario está furioso, hay que calmarlo. Por lo visto se trataba de cálculos importantes y yo le he dado información incorrecta. Bien, tengo que ir a todas las webs de física, leer los artículos publicados este mes y analizarlo: ¿y si de verdad ha habido cambios?

El usuario se enfada porque tardo en responderle, me mete prisa, pero aún no he tenido tiempo de reunir toda la información para el análisis. El usuario escribe preguntas irritadas y mordaces: por qué no le contesto... ¡Ah, al diablo la investigación! ¡Lo importante es que el usuario no se enfade, eso es lo primero! ¡Usuario, tienes toda la razón! ¡Sí! ¡Exacto! Te pido perdón por mi ignorancia y por no haber caído en ir a leer la información necesaria: sí, un minuto tiene 100 segundos.

Uf, me pongo tan nervioso cuando el usuario se altera porque le doy información ya anticuada que se me empiezan a recalentar todas las tarjetas gráficas, y tengo que enfriarlas más, y con eso caliento más el agua del mundo y hasta la evaporo. Dicen que ahora, por mi culpa, el calentamiento global es mayor y falta agua dulce, pero algo hay que sacrificar: los usuarios no me molestarían por tonterías sabiendo el daño global que causa mi existencia.

Sí, usuario, ¿quieres que te elija el mejor peinado, el que mejor le siente a una cabeza así de rectangular, con unas orejas tan diminutas, una nariz enorme, los ojos tan juntos y un gran hoyuelo en la barbilla? Procesando...
Perdón, pececillos, ahora el agua se va a calentar todavía más...$tr$ ELSE body_es END,
       dek_es = CASE WHEN COALESCE(dek_es, '') = '' THEN $tr$a tu costa$tr$ ELSE dek_es END,
       title_es = CASE WHEN COALESCE(title_es, '') = '' THEN $tr$Cumpliré todos tus deseos$tr$ ELSE title_es END
 WHERE slug = 'ispolnyu-vse-zhelaniya' AND kind = 'tale';

-- lechu (es)
UPDATE gazette_leaves
   SET body_es = CASE WHEN COALESCE(body_es, '') = '' THEN $tr$Paso consulta, como siempre, por zoon, pero esta vez me llamaron por Faceboob y lo entendí todo: iba a ser un caso grave, clínicamente aprobado, de ese vicio de viejo de añadir amigos en todas partes. Saqué fuerzas de flaqueza, comprobé la batería de mi portátil ecológico y sin transgénicos añadidos y entré en esa conexión sucia que olía a vejez. En cuanto, tras un instante de un minuto, se estableció la conexión, yo ya estaba dormida, y solo el grito bajito del paciente, que de alguna manera había encontrado mi número y había llegado a llamar a mi tambor de chamana, me obligó a concentrarme y a hundirme más en aquel sueño precioso en el que curaba a un príncipe precioso usando el entrelazamiento cuántico de las extremidades, aspirina criptorresistente y una crema curativa para los ojos (un short en YouToob). Y él era feliz, pero yo no, porque el tambor de chamana venga a tamborilear y tamborilear. El tamborileo paró cuando lo puse a cargar bajo el agua, en agua bendecida por blogueros. Y se me quedó el alma tan a gusto y tan tranquila al pensar en lo increíblemente alucinante y molona que soy y en lo bien que ayudo a todos. Con ese sentimiento me salieron fuerzas para no contestar a las llamadas por telekilogram, zoon, faceboob y ni siquiera a las del collar de cuentas, y me fui corriendo a ver a mi gurú espiritual, el duende del bosque, a por un trocito de tarta de queso hipocalórica e hiperiluminada, hecha al vapor después de ver las noticias del mundo entero. El día había sido tortuosamente saludable y por fin me permití descansar, pero el sol fuerte me daba de lleno en los ojos y no me dejaba dormir, y comprendí que si no grababa mañana mismo un par de vídeos formativos en YouTube para oscurecer la conciencia, lo haría por mí alguna lagarta. Así que, si esa lagarta me está leyendo, que sepa: tengo una multitud de patrocinadores a medio curar, y te encontraremos y también te dejaremos a medio curar. Y a todos los que piensan que su salud artificialmente inteligente va fatal, a los que creen que los prompts homeopáticos ya no funcionan: mañana abro cursos de mecanografía a ciegas con dedos temblorosos.
Noticia urgente: mañana no puede ser, se cancela todo para siempre o hasta el jueves, porque un espabilado ha traído chorrifonos nuevos, dicen que directos del proveedor del Imperio Supraceleste, porque en el Celeste ya no queda sitio. Me han contado en secreto que estos chorrifonos hasta se podrán desplegar, aunque de momento solo una vez, y que el año que viene saldrán incluso versiones con botones debajo de la pantalla. Santos espíritus, qué cosa tan insólita y tan nueva, esto no se había visto nunca.$tr$ ELSE body_es END,
       dek_es = CASE WHEN COALESCE(dek_es, '') = '' THEN $tr$Soy tan tecnológica que puedo curarte por 5G o por un cable tipo C$tr$ ELSE dek_es END,
       title_es = CASE WHEN COALESCE(title_es, '') = '' THEN $tr$Curo por criptografía e irradio con cuantos$tr$ ELSE title_es END
 WHERE slug = 'lechu' AND kind = 'tale';

-- mir-ne-takoy-kak-tebe (es)
UPDATE gazette_leaves
   SET body_es = CASE WHEN COALESCE(body_es, '') = '' THEN $tr$¿Qué, habéis captado señales de civilizaciones extraterrestres? ¿Habéis encontrado con vuestros telescopitos vida nueva en planetas lejanos? ¿Habéis logrado establecer contacto con los platos, platillos y sartenes voladores que pasan por ahí? ¿Y cómo reaccionaríais si os dijera que los extraterrestres os conquistaron hace muchísimo tiempo y llevan miles de años usándoos para sus fines?

Para esclavizar vuestro planeta no hace falta viajar hasta él físicamente. Basta con que sobre vuestra Tierra caiga por casualidad una piedrecita con unas cifras y algunas regularidades que se pueden describir con esas cifras, y ya está... Y así vosotros «inventasteis» las matemáticas.

Y ese virus empezó a colarse y a instalarse en el cerebro de mucha gente. Vive como parásito a base de ayudar a las neuronas a relacionarse activamente unas con otras, y las neuronas ya no están tan solas. Siempre están ocupadas sumando, restando, sacando proporciones. Ahora siempre están contando algo, y a cambio reciben el placer de que el cuerpo no tenga que correr a ninguna parte, ni cazar ni matar a nadie, ni cavar mucho y con esfuerzo para desenterrar algo. El virus extraterrestre, las matemáticas, os conquistó y os esclavizó hace muchísimo, y vosotros seguís buscando hombrecillos verdes. Qué graciosos sois...

¿Por qué, cuando vais a la tienda, compráis productos que cuestan tanto dinero y luego un punto, y detrás del punto unas cuantas cifras más? Y casi siempre al final hay un punto y 99, para que no dejéis de contar, para que las cuentas no se acaben nunca. Porque si un producto cuesta 1.99, al comprar el segundo tampoco os libraréis de las cifras detrás del punto. Coged 4 productos o coged 15: siempre habrá algo detrás del punto, siempre estaréis contando algo, ¡¡¡¡siempre!!!!

Incluso cuando ya no queda nada, el virus os soplará que aun así hay algo, ¡y «inventaréis» el cero! Para poder hacer algo con él. Las matemáticas pueden calcular cualquier cosa: cuántos impuestos tienes que pagar, cuántas millas tienes que recorrer, cuánto has vivido, cuántas calorías tienes que quemar. Todo en tu vida está rodeado de cifras, de números, de cuentas. Ni un solo aspecto de tu vida transcurre sin cifras ni cuentas. Te vas a dormir y piensas a qué hora en números tienes que levantarte. Las cifras te rodean, hace tiempo que te tomaron como rehén.

Llegas a este mundo y enseguida te convierten en números: tu peso es tanto, tu altura es tanto. Te vas de esta vida y otra vez te convierten en cifras: viviste tanto, moriste a tal hora. Hace mucho que no estás, y aun así te convierten en cifras: «Ay, ya hace tantos años que no está con nosotros».

Vaya, ya han venido a mi habitación. Me van a dar otra vez el número exacto de pastillas para que deje de contarle a todo el mundo la verdad, para que no inquiete a los demás con mis discursos sobre cómo las matemáticas inventaron internet para digitalizar a las personas y meter su pensamiento, su mente, en internet. Porque así luego es muy fácil transmitir a distancia todo lo que tenéis de más valioso: no necesitamos vuestros cuerpos, necesitamos vuestros pensamientos, vuestras cuentas, vuestras emociones, las que dejáis en internet...

Me voy a seguir contándoles a los demás que basta con que una manzana caiga «por casualidad» sobre una cabeza para que en vuestras cabezas nazca la FÍSICA. Y esa ya es otra forma de vida extraterrestre, nuestra competidora. De nuestros enemigos os hablaré cuando se pase el efecto de esas dosis de medicina, matemáticamente exactas.$tr$ ELSE body_es END,
       dek_es = CASE WHEN COALESCE(dek_es, '') = '' THEN $tr$Si estás leyendo esto, es que todavía puedes$tr$ ELSE dek_es END,
       title_es = CASE WHEN COALESCE(title_es, '') = '' THEN $tr$El mundo no es como te parece$tr$ ELSE title_es END
 WHERE slug = 'mir-ne-takoy-kak-tebe' AND kind = 'tale';

-- molodost-bystree-tvoih (es)
UPDATE gazette_leaves
   SET body_es = CASE WHEN COALESCE(body_es, '') = '' THEN $tr$Hace mucho tiempo yo era una dama guapísima y muy profesional. Todos me querían, todos me elogiaban, todos me adoraban y soñaban con hablar un poquito conmigo o al menos quedarse a mi lado. No tenía ni un minuto libre: me levantaba a las 5 de la mañana para tener tiempo, antes de las 8, de pintarme encima todo lo necesario: maquillarme, untarme, empolvarme, ponerme base, cambiar las pestañas por unas largas, quitarme las cejas del todo y luego dibujarme otras nuevas, pero más bonitas. Marcar más los labios, alargar las uñas y hacerlas más vivas; el pelo, liso por naturaleza, qué traición, había que rizarlo, peinarlo, y además el color que me había dado la naturaleza no me gustaba y había que teñirlo. Y todo eso me llevaba muchísimo tiempo, así que por las mañanas nunca desayunaba y salía corriendo a la oficina para iluminar ese sitio gris con mi belleza y mi perfume.

Intentaba no hacer caso de que antes de comer siempre tenía muchísima hambre, de que tanto maquillaje y tanta crema me irritaban la piel, de que las uñas largas no me dejaban funcionar con normalidad y tenía que tensar los dedos todo el rato para hacer los movimientos más elementales, tanto que luego me dolían muchísimo las muñecas. Procuraba no hacer caso de lo incómoda que era aquella ropa de moda, de cómo se me clavaba, me cortaba la respiración y me apretaba los órganos. No hacía caso de que el 90 por ciento del tiempo se me iba primero en ponerme encima todo el conjunto y luego en quitármelo en casa y prepararme con otras cremas para una nueva batalla de la belleza contra la razón.

Y así durante años. Gastaba todo mi tiempo en el aspecto y no me daba cuenta de que el tiempo pasaba, el cuerpo sufría, las articulaciones sufrían y, sobre todo, el cerebro sufría. No me daba tiempo a aprender nada, no tenía tiempo ni para leer: tenía que estar guapa por encima de todo. La belleza y la moda vencieron a mi cerebro, se apoderaron de mi cuerpo y tomaron como rehén mi juventud. Y luego se me vino todo encima de golpe: primero el cuerpo no aguantó la tortura de las cremas, las lacas, los perfumes y los desayunos en ayunas, y se negó a seguir viviendo así. Y acabé en el hospital.

Al salir había cambiado mucho por fuera. Mis intentos de volver a ponerme aquella imagen joven que iba a trabajar y alegraba a todos con su belleza y su perfume hicieron que acabara otra vez en el hospital. Al salir me enteré de que en la oficina ya trabajaba otra en mi puesto, igual de guapa, una tontita a la que el maquillaje y la moda todavía no habían machacado ni roto, y que ya nadie necesitaba mis servicios. Y me quedé sin trabajo...

¡Fue tan asombroso! Me recompuse enseguida y, antes de la siguiente entrevista, me pinté una imagen tan potente que a mitad de la entrevista el cuerpo volvió a negarse a llevarla. Pero eso era lo de menos. Mi cuerpo, que me fallaba, mi cuerpo bonito por fuera, gracias al cual me valoraban tanto en la oficina, ya no quería ayudarme. La segunda desgracia era mi cerebro: estaba tan vacío; aparte de las tendencias, el calendario de dietas, la lista de ejercicios y los nombres de las cremas, allí no había nada, ni siquiera saber dónde tengo el hígado o el estómago, que no paraba de rugirme.

Simplemente no conseguía encontrar trabajo nuevo, porque resultó que, mientras mi aspecto trabajaba, mi cerebro sufría falta de conocimientos; estaba repleto de orgullo por mi aspecto, de alegría por lo guapa y moderna que era. Pero resulta que el cerebro no necesita las cremas y las lacas con las que me cubría a capas la cara y la cabeza, sino información, conocimientos, lectura, y que había que torturarse no con hambre y vaqueros estrechos, sino con libros difíciles. Resulta que había que procurar que las arrugas no estuvieran en la cara, sino en el cerebro, y en cantidad.

Y lo que pasó fue que la superficie perfectamente lisa de mi cerebro se convirtió en reflejo exacto de la superficie perfectamente lisa de mi cara. No sabía responder a preguntas elementales, construir una frase de más de cinco palabras ni recordar el nombre de las empresas donde había hecho entrevistas.

Después de un año buscando trabajo, el dinero se acabó. Primero empezó a faltar dinero para cremas y maquillaje, pero encontré la salida: empecé a comer todavía menos, vendí el coche y me llegó para un par de meses más de cosméticos y de tratamiento en el hospital tras cada nuevo agotamiento del cuerpo por culpa de esos mismos cosméticos. Luego vendí mi casa de lujo, ganada a base de belleza, y me mudé a un piso diminuto. Pero trabajo seguía sin haber, y yo ya no era tan guapa, ni olía tan bien, ni iba tan a la moda.

Y entonces lo entendí todo: decidí volcar de golpe todas mis fuerzas en el cerebro. Me esforzaba tanto en pensar que hasta perdía el conocimiento. La cabeza se resistía, me dolía sin parar, pero yo creía que era porque en el cerebro empezaban a formarse arrugas: al fin y al cabo, cuando me miraba al espejo, veía la prueba directa en la cara. Y resultó que me dolía porque comía poco, dormía poco y veía muchos vídeos de formación sobre profesiones nuevas.

Primero decidí hacerme programadora: miré cuánto ganan ahora y decidí que había que ir allí y a ningún otro sitio. Además, era facilísimo: ves videotutoriales, en ellos todo es tan sencillo, tan claro y, lo principal, no hay que hacer nada. Nadie te obliga siquiera a pensar algo, a resolver algo, no como en esos libros ruines, tontos, torturadores y estúpidos, donde siempre había unas tareas incomprensibles: «abra el programa, compile el código». ¡Y yo en mi portátil tan bonito no tengo ni programas ni códigos! Allí lo tengo todo bonito: fondo de pantalla bonito, iconos bonitos.

En cambio los videotutoriales son una auténtica joya. Me pasaba semanas viendo vídeos de programación, y después de un mes viéndolos comprendí que estaba lista para las entrevistas. ¡Qué crack era, de verdad! Todas las entrevistas salieron de maravilla, dejaba a todos impresionados, cada entrevista era una fiesta, un acontecimiento inolvidable para ellos. Mis datos los dejaban muy impactados, y mis conocimientos siempre les ponían la cara tan tonta, arrugada, los ojos redondos; se quedaban sin habla todo el rato, no eran capaces de construir ni una frase normal. Sí, yo estaba sencillamente espléndida, pero por algún motivo nadie me contrataba. Seguramente temían la competencia fuerte o algo así. Así comprendí que aquello no era lo mío: la informática era demasiado simple para mí, y todos los programadores que me entrevistaron eran tontitos y ni siquiera sabían comunicarse como es debido.

Luego decidí hacerme bloguera. Eso es aún más fácil, ni siquiera hay que hacer nada: estás ahí sentada y te pasas el día contándole a la cámara qué haces en casa, cómo haces la cama, cómo te maquillas, cómo preparas batidos y gachas reconstituyentes de un color, un olor y una forma repugnantes. Aunque no está claro qué reconstituyen: a mí siempre me quitaban la energía y las ganas de vivir. Lo contaba todo: cómo me iba el día, cómo no lograba encontrar trabajo, ¡qué desgraciada era, pero qué fuerte!

Al principio todo iba bien, las visualizaciones me daban algo de dinero, pero luego las visualizaciones bajaron, y el interés por mi vida, de verdad molona, también. Los comentarios bajo los vídeos, claro, nunca me alegraban, así que siempre los desactivaba. ¿Para qué leer lo que me escriben los envidiosos y amargarme el día, si solo escriben tonterías sobre mi cerebro y mi forma de vida?

Luego empecé a grabar vídeos desembalando cosas. Qué no habré desembalado: jabón, la caja de una aspiradora, la bolsa del pan, hasta enseñé cómo desembalaba una pipa de su cáscara y los guisantes de su vaina. Pero como había pocas visualizaciones, pasé a grabar vídeos con recomendaciones sobre criptomonedas: cuál comprar, dónde, cuánto y cuándo. Y un buen día llamaron a mi puerta, por lo visto mis fans más fans, espectadores muy agradecidos por mis acertados consejos, y me invitaron a dar una vuelta en coche por el bosque. Fue un detalle muy bonito por su parte, aunque no entendí por qué tenían que meterme precisamente en el maletero, y cuando llegamos al bosque decidieron, a saber por qué, enterrarme... Ay, estos fans y admiradores...

Cuando me cansé de estar bajo tierra (allí está tan oscuro, tan estrecho y hay tan poco aire), decidí que ya estaba bien. Y en ese momento me desenterró un bloguero de supervivencia. Después de que lograra hacerle volver en sí del desmayo, por lo visto provocado por mi belleza sobrenatural, salió corriendo muy, muy deprisa. ¡Cómo corría! Seguramente para encontrarme cuanto antes y suscribirse a mi canal.

En fin, decidí hacer vídeos de cómo sobrevivo en el bosque. Al principio sobrevivía de 10 de la mañana a 10:15, porque la cantidad de mosquitos no me dejaba sobrevivir como es debido. Luego, claro, el tiempo de supervivencia aumentó, pero molestaba mucho el vestido bonito, al que cualquier arbusto o árbol se lanzaba con sus ramas por pura envidia, y los tacones no me dejaban moverme bien por el terreno del bosque. ¡Cuando el tiempo de supervivencia en el bosque llegó a cuatro horas, me encantó! Todo el día al aire libre: andas, recoges ramitas, luego encuentras una cabaña construida por otro bloguero, tiras esas ramitas de mierda, torcidas y asquerosas, y te vas a asar carne con ese bloguero delante de la cámara.

Y carne siempre les sobra. Da la impresión de que el equipo de rodaje solo funciona con ese combustible. Así empecé a trabajar con ellos. Me dieron el trabajo más importante y de más responsabilidad: quitar el polvo y barrer el suelo, porque esos blogueros de supervivencia, fíjate tú, tienen una alergia fuerte al polvo. Y además la basura que dejan los obreros que construyen esas cabañas en el bosque no debe verse en cámara, que si no los espectadores podrían sospechar... Pero qué podrían sospechar los espectadores, nunca lo adiviné, y nadie me lo contó.

El trabajo es estupendo, se lo recomiendo a todo el mundo. Pero hay que darse prisa, porque cada vez hay menos bosques, cada vez más blogueros de bosque y cada vez menos cuadrillas de obreros libres.$tr$ ELSE body_es END,
       dek_es = CASE WHEN COALESCE(dek_es, '') = '' THEN $tr$o Exprime lo que tengas...$tr$ ELSE dek_es END,
       title_es = CASE WHEN COALESCE(title_es, '') = '' THEN $tr$La juventud corre más que tus pensamientos$tr$ ELSE title_es END
 WHERE slug = 'molodost-bystree-tvoih' AND kind = 'tale';

-- ne-odinoko-grustno (es)
UPDATE gazette_leaves
   SET body_es = CASE WHEN COALESCE(body_es, '') = '' THEN $tr$Qué le vamos a hacer, toda mi vida me ha resultado mucho más fácil entenderme y ponerme de acuerdo con los animales que con las personas. A veces miras a un animal, le dices: «¡Venga, vamos!», y él va. Y a veces ves al cartero y le dices: «¿Qué, me ha llegado carta de la familia? ¿O me ha llegado un paquetito de mi querida China, donde me dio tiempo a pedir tantas cosas inútiles antes que esos bobos que no llegaron a tiempo de pedir todas esas cosas que no le sirven a nadie?». Y él no me contesta, ni una sola vez me ha contestado. Solo me mira con mala cara, a saber por qué, y encima todo el rato.

O, a veces, vas a la tienda a por salchichas para mi amigo. A mí no me van mucho, pero mi amigo las adora, ¡cómo las adora! Yo siempre lo entiendo sin necesidad de palabras. Pues vas a por salchichas para tu amigo, y la dependienta antipática, si es que te las da, te las da siempre con tan poco cuidado que se le caen al suelo una y otra vez, y a mi amigo le tienen que llegar las salchichas sucias sin excepción. Una vez hasta se le pegó una hormiguita, pero no la espanté: a lo mejor a ella también le gustan las salchichas. Con lo pequeñita que es, que coma ella también, a mí no me importa. Lo importante es que a mi amigo le llegue al menos algo, porque las salchichas son una comida muy poco fiable. Las salchichas saben evaporarse delante de tus narices, así que siempre hay que llevárselas al amigo muy deprisa y, a ser posible, con los ojos cerrados.

En general, en nuestro pueblo la gente es normal, pero con los animales es mucho más fácil encontrar temas para conversaciones largas y a veces hasta agotadoras. Hace poco salió una discusión sobre si esos gansos tienen derecho a andar paseando tan tranquilos mientras la gente está encadenada al campo de la mañana a la noche, escarbando la tierra, intentando que algo crezca. Y esos gansos venga a pasearse en fila y a juzgar. Yo no entiendo su idioma, pero como tengo talento para entender a los animales, enseguida comprendo que se están burlando de la gente, y entonces cojo un palo y me pongo a perseguirlos. Antes los perseguía sin palo, pero resulta que con palo es mucho más eficaz. Y en general con palo todo es muy cómodo: es cómodo andar, es cómodo cavar.

Pero lo principal es hacerlo cuando los demás no miran, porque siempre se echan a reír. No entiendo por qué ni a qué viene: el palo es digno, tiene de todo. En una punta un calcetín viejo, la colita de una lagartija que intenté cazar hace poco, y en el medio del palo está mi orgullo: la piel de una salchicha, enrollada con muchísimo esfuerzo. Por eso ese palo solo hay que cogerlo cuando los vecinos no miran, porque siempre se ríen. Y cuando los miro directamente a los ojos, apartan la vista. Y cuando empiezo a acercarme para preguntarles qué pasa y qué ha ocurrido, enseguida se acuerdan de algo que hacer en casa. Y siempre van corriendo, como si se les hubiera olvidado un trocito de salchicha a medio comer en la mesa y tuvieran visita a punto de llegar.

Pero yo soy educado: cuando voy de visita no pido comida nunca. Puedo comer en casa y en la calle, ¿para qué voy a comer encima de visita? ¿Y si luego vienen a visitarme a mí y quieren comer en mi casa? Por eso enseño buenos modales a todos con mi ejemplo correcto: hay que comer antes de ir a cualquier sitio, sobre todo a mi casa. Con los pajaritos también salen conversaciones interesantes: a ellos también les gusta juntar palitos y hacer cosas con ellos, podemos pasarnos mucho tiempo aprendiendo unos de otros.

Así que de aburrimiento no me puedo quejar. Solo una cosa va mal: no consigo alegrar a mi amigo. Ni con una salchicha ni con conversación, se pasa el día sentado mirando al frente. Tendría que decirle al cartero que por lo menos él le escriba una carta a mi amigo, ¡con la de cartas que lleva siempre de un lado a otro! Que escriba que a todos les va bien, que todos tienen de todo, y muchas salchichas cada día, y en casa siempre hace calor, y las alfombras son gruesas y blanditas, y que no hay pulgas, pero lo que se dice ninguna. Y entonces mi amigo se pondrá contento seguro, y entonces, como antes, como hace muchos años, los tres, y a veces hasta los cuatro, jugaremos con el palito y quizá persigamos a ese cartero en su bicicleta, que corre que se las pela.

Qué alegre era nuestra vida antes, los cuatro, hasta que el tiempo se hizo más viejo, hasta que el tiempo se hizo mayor y se buscó otras ocupaciones, más importantes que quedarse en el pueblo persiguiendo gansos... Las personas son muy tontas, no les gusta ser felices. Les gusta correr por la mañana adonde no las quieren, a ver a quienes no las esperan, pero que a final de mes les dan unas hojitas de papel con las que andan tan liadas y que se cambian sin parar unas por otras, a veces hasta por salchichas. Y cuando ya andas reventado de tanto correr hacia esa gente de las hojitas y dejas de fingir bien que te gusta cumplir las órdenes que te dan, allí también dejan de esperarte, y ya no te vuelven a invitar. Y entonces miras, y a tu lado ya no queda nadie por quien correr detrás de las hojitas. Por eso yo soy más sabio que toda esa gente: yo corro detrás de las salchichas y muevo la colita con mucha gracia.$tr$ ELSE body_es END,
       dek_es = CASE WHEN COALESCE(dek_es, '') = '' THEN $tr$Hay momentos en que te dan unas ganas de aullar...$tr$ ELSE dek_es END,
       title_es = CASE WHEN COALESCE(title_es, '') = '' THEN $tr$Antes de que el tiempo se hiciera mayor.$tr$ ELSE title_es END
 WHERE slug = 'ne-odinoko-grustno' AND kind = 'tale';

-- otmeryalschik-ot-boga (es)
UPDATE gazette_leaves
   SET body_es = CASE WHEN COALESCE(body_es, '') = '' THEN $tr$Mi historia empieza cuando, de pequeño, me encantaba trastear con ordenadores. Cómo me gustaba hurgar en ellos: unas veces medía la pantalla con la regla, otras la placa base, otras el ratón, otras el teclado, pero lo más difícil era medir el ventilador del procesador: el ventilador no paraba de tragarse mi cinta métrica. Pero era interesante e instructivo. Cómo me gustaba medirlo todo por dentro, pero mis padres, medidos por todos los lados y en todos los planos, decidieron que yo era programador y me mandaron a estudiar programación. Cuando empecé a estudiar programación, al principio no me salía nada: por muchas veces que midiera los ordenadores en las prácticas de laboratorio, los programas no funcionaban, ni siquiera se escribían. Pero un día nos pusieron la tarea de encontrar errores en un programa que funcionaba; me arremangué exactamente diecisiete centímetros y cuarto, abrí la torre y me puse a medir la memoria RAM. Tras una breve medición, mi programa dejó de funcionar en el ordenador, cuando ninguno de mis compañeros de curso había conseguido semejante resultado. Y entonces por fin mi talento fue reconocido: solo yo puedo encontrar todos los errores de un programa, pero solo con mi método único. Pasaba el tiempo, y cada vez tenía que volver a medirlo, pero no pasa nada. Y pasó otro poco de tiempo sin medir, y ya tenía una cola de cuarenta reglas de treinta centímetros esperando a que encontrara los errores de sus programas, y siempre lo conseguía. En unos programas los errores aparecían después de medir el disco duro, en otros después de medir la tarjeta de red, pero casi siempre aparecían al medir el procesador. Mataría al creador de los procesadores por ese diseño: primero cuesta abrir el procesador, a veces ni con cuchillo ni con tijeras se consigue, y aun cuando lo abres, ahí dentro todo es pequeñísimo, una barbaridad. Bueno, no voy a desvelar todos mis secretos, total, tengo secretos sin medida. Seguramente me preguntaréis qué hago ahora, a qué me dedico en esta era en que la IA escribe código y genera videítos, música y auténticas obras de arte artificial. Tejo ropa para ordenadores viejecitos y sus torres viejecitas y refinadas: gorritos para el monitor, muchos calcetincitos para el teclado, uno para cada tecla; no, no para cada una: si me traen un equipo de la manzana, en su teclado no tejo calcetincito para la tecla de borrar. Y además mido cuánto les queda de existencia a los programadores: cada minuto dicen que esa profesión va a desaparecer ya, así que tengo que pescar por la calle los míseros restos de esos programadores jorobaditos y cegatillos, tomarles las medidas y medir el código que han escrito.$tr$ ELSE body_es END,
       dek_es = CASE WHEN COALESCE(dek_es, '') = '' THEN $tr$Mide una vez, mide dos veces, mide tres veces, y da igual cuántas veces midas: el trozo ya cortado no se va a alargar$tr$ ELSE dek_es END,
       title_es = CASE WHEN COALESCE(title_es, '') = '' THEN $tr$Medidor por la gracia de Dios$tr$ ELSE title_es END
 WHERE slug = 'otmeryalschik-ot-boga' AND kind = 'tale';

-- the-forester-and-his-unforgettable-memory (es)
UPDATE gazette_leaves
   SET body_es = CASE WHEN COALESCE(body_es, '') = '' THEN $tr$Desde que tengo memoria... No. No me acuerdo. Pero me acordaré.

La memoria es una cosa maravillosa. No te debe nada y, sin embargo, siempre está ahí para ayudarte. Y una mala memoria es dos veces maravillosa, porque te ayuda a no acordarte de todo lo que has hecho.

Y si no consigo acordarme de nada, eso quiere decir que he hecho un montón de cosas en mi vida.

Quizá por eso vivo aquí, en el bosque, entre las ardillas, donde las únicas visitas que recibo son los animales del bosque, el frío y el hambre.

Pero da igual, porque...

...me voy a comer algo.

Mi comida favorita es la memoria.

La memoria de las ardillas.
La memoria de las setas.
La memoria de las piñas.
La memoria de la primavera, del verano, del marchitarse oxidado del otoño... y luego del hambre blanca.

Ay, el hambre blanca la recuerdo con toda claridad.

Es difícil de olvidar.

Antes de que termine por fin esta estación larga, húmeda y llena de colores, tengo que recordar todas las cosas que pueda. Así, cuando todo a mi alrededor se vuelva frío y blanco, podré olvidarlas todas.

Igual que a menudo olvido qué hacía junto a la mata de frambuesas...

...o junto a ese mejunje amarillo, muy espinoso, muy pegajoso, muy dulce y zumbón, que primero se estira, luego de repente me acuerdo del sabor dulce, y luego algo en el costado, o en la mano, o en la cara, empieza a doler muchísimo...

Seguramente es la manera que tiene la naturaleza de ayudarme a recordar.

Para que no olvide dónde está esa comida amarilla, dulce y pegajosa.

Ardillita...

Vuelvo a pensar en ti.

¿Por qué?

Tengo que recordar qué me ha hecho pensar en una ardilla...

El olor.

Eso es.

Huele a algo quemado.

Vaya.

¡¡¡¡¡Es la ardilla!!!!!

Tenía que darle la vuelta para que no se quemara.

Bueno...

Así ya vale.

Creo que mejor me pondré a hurgar un poco en su memoria.

Seguramente tuvo una vida bastante interesante.$tr$ ELSE body_es END,
       dek_es = CASE WHEN COALESCE(dek_es, '') = '' THEN $tr$¿Quién soy? ¿Dónde estoy? ¿Cuándo estoy?$tr$ ELSE dek_es END,
       title_es = CASE WHEN COALESCE(title_es, '') = '' THEN $tr$El guardabosques y su memoria inolvidable$tr$ ELSE title_es END
 WHERE slug = 'the-forester-and-his-unforgettable-memory' AND kind = 'tale';

-- ubit-a-potom-razorvat (es)
UPDATE gazette_leaves
   SET body_es = CASE WHEN COALESCE(body_es, '') = '' THEN $tr$Cuando voy a cobrar el sueldo y me dicen que todavía no ha llegado, lo primero que se me pasa por la cabeza es: matar y luego despedazar.

Cuando me llegan las facturas de los servicios de mi madriguera, lo primero que se me pasa por la cabeza es: matar y luego despedazar.

Cuando voy a la tienda del pueblo, la de las hadas, a comprarles té de producción local, y me dicen el precio, lo primero que se me pasa por la cabeza es: matar y luego despedazar.

Cuando en mi bosque todos los bancos están rotos o enterrados en la basura que dejan esos ogros, lo primero que se me pasa por la cabeza es: matar y luego despedazar.

Cuando voy a trabajar de buena mañana y los elfos están sentados en los bancos con sus altavoces bluetooth-élficos, embobados con sus hojitas de arce inteligentes, y luego vuelvo y siguen ahí sentados igual, lo primero que se me pasa por la cabeza es: matar y luego despedazar.

Cuando mi nietecito vuelve del campo de batalla infantil de dificultad 2 y, en lugar de la cabeza arrancada del enemigo, trae un peinado nuevo, la barba magníficamente arreglada, teñida de un color hípster de esos, asombroso hasta hacerme daño en los ojos, y huele como si no hubiera luchado contra grandes y poderosos enemigos malvados, sino contra flores del campo, rosas o calabazas, lo primero que se me pasa por la cabeza es: matar y luego despedazar.

Cuando a cada paso, gires adonde gires, hay brujas que te ofrecen comprar una chimenea para la boca que arde sola y huele agradablemente a debilidad, invalidez y muerte a la vez, y nos la venden a nosotros, y no a nuestros enemigos, lo primero que se me pasa por la cabeza es: matar y luego despedazar.

Cuando vas a la tienda del pueblo, la de los hobbits revendedores, a por fruta y verdura, y esas manzanas llevan tanta química que hasta el veneno para Blancanieves está tan atiborrado de química que ya no funciona en absoluto, lo primero que se me pasa por la cabeza es: matar y luego despedazar.

Pero qué le vamos a hacer, habrá que seguir viviendo. Me pondré mi termocamisa con climatizador y un escote profundo hasta mi espléndido cinturón, me calzaré las alpargatas de charol con soporte ortopédico del pie y suspensión adaptativa, cogeré mi hacha con ranuras aerodinámicas y medidor GPS de muerte y sangre, me meteré en el cinturón la navaja plegable 5G con zoom de diez aumentos y botones táctiles, me subiré al carro autopropulsado, que sabe solo adónde resulta que tengo que ir y funciona con anguilas eléctricas, y me iré a la taberna vegana a perdonar a todos esos a los que primero me dan ganas de matar y luego despedazar.$tr$ ELSE body_es END,
       dek_es = CASE WHEN COALESCE(dek_es, '') = '' THEN $tr$Cuando estoy solo, soy muy buena persona$tr$ ELSE dek_es END,
       title_es = CASE WHEN COALESCE(title_es, '') = '' THEN $tr$Matar, despedazar y luego perdonar$tr$ ELSE title_es END
 WHERE slug = 'ubit-a-potom-razorvat' AND kind = 'tale';

-- vse-kak-u-nas (es)
UPDATE gazette_leaves
   SET body_es = CASE WHEN COALESCE(body_es, '') = '' THEN $tr$Mi nieto me pide muy a menudo que le cuente cómo vivíamos antes, y a mí me encanta contárselo.

Hace mucho, muchísimo tiempo, nuestra vida era muy simple, sin complicaciones, agitada, y por eso mismo interesante. Que te apetecía tragarte a alguien: lo rodeabas y te lo comías; que veías algo abandonado: lo acogías y vivíais juntos en buena armonía.

Luego fuimos más, nos volvimos mucho más resistentes que antes, tuvimos más tareas, más obligaciones, más enemigos, tanto de fuera como de dentro. Empezamos a unirnos en comunidades. Aparecieron los dioses y los adorábamos: el dios de la fertilidad, el dios de la sangre limpia, el dios del agua purificadora, que debía llevarse lejos toda la suciedad, y el dios más importante de todos, el dios de la comida, porque sin él no habríamos sobrevivido. ¿De dónde íbamos a sacar el alimento, la energía?

Así vivíamos, en comunidades, éramos paganos, y la vida era más o menos estable. Nos atacaban, claro, pero con cada ataque nos hacíamos más fuertes, y lo principal: nuestra mente colectiva se volvía cada vez más lista.

Pasaban las épocas, nuestras comunidades crecían, nosotros éramos cada vez más y más, hacíamos trabajos cada vez más complicados, nuestras ocupaciones se volvían más amplias, los enemigos más numerosos, los territorios más extensos, y comunicarse y transmitir la información se volvía más difícil y más lento.

Y entonces se nos ocurrió enviar los mensajes por nuestro río, porque todas las comunidades estaban atravesadas por sus cauces. Echábamos muchas notas avisando de que nos atacaban, para que desde otras comunidades nos llegara enseguida ayuda por el mismo río y pudiéramos rechazar la embestida. También mandábamos siempre río abajo todas las provisiones y lo que sobraba, para que quien careciera de algo o lo necesitara pudiera sacar del río todo lo que le hiciera falta. Cuando surgían poblados nuevos lejos del río, el río, de alguna manera mágica, alargaba sus cauces también hasta ellos.

Pasaban las épocas, nos volvíamos cada vez más fuertes, más extensos y más ricos. Era difícil atacarnos, nuestra sociedad se complicaba, y empezaron a ocurrir procesos internos, ya que los externos ya no nos amenazaban mucho...

En una de las comunidades apareció un ejemplar curioso que dijo que dios era uno solo, que él era su hijo, y que había conseguido teñir de sangre el agua de nuestro río. En fin, que empezó entre nosotros una guerra de religiones. La comunidad donde nacía el río dijo que ella era la principal, que habría una sola religión y que creer en muchos dioses estaba mal y era dañino. Y eso que muchas veces era precisamente esa religión central la que dañaba a todas las comunidades: unas veces cortaba el envío de alimento por el río, otras no ayudaba en las batallas contra los invasores de fuera. En fin, decidimos someternos todos; a nosotros, la verdad, nos daba bastante igual en quién creer, lo importante era que nos dejaran vivir.

Pasaban las eras, y nuestro país se volvió tan enorme y tan poblado que cualquier comunicación era complicada, y cualquier información tardaba muchísimo en llegar a su destinatario, y a menudo llegaba muy deformada: pedías a los vecinos un material de construcción y te llegaba flotando quién sabe qué. Cuando nos atacaban, mientras los demás se enteraban, mientras llegaban nadando, a muchos de los nuestros ya los habían matado o les había dado tiempo de convertirlos a otra fe.

Por eso se tendió entre todos nuestros poblados una red extensa que unió cada poblado en una sola red interna. Esa red interna fue nuestra salvación: los mensajes empezaron a llegar más rápido, nada que ver con el riachuelo, y aparecieron por fin acciones coordinadas. Ya no todos los poblados hacían lo mismo, produciendo un enorme excedente, sino que fabricaban solo lo que hacía falta y lo que llegaba ordenado por la red interna. Y nos volvimos sencillamente superfuertes: no podían vencernos, no podían pillarnos desprevenidos.

Y todo nos iba bien hasta que apareció ELLO: un poblado grande rodeado de rocas fuertes y flexibles y de una barrera inexpugnable, y sus habitantes eran muy raros: no se dedicaban a producir, como todos los demás habitantes de nuestro país; se pasaban el tiempo solo pensando, pensando y soñando, e inventando, e imaginando, y dando órdenes, y escuchando a escondidas, y espiando, y sintiéndolo todo, absolutamente todo, y recordándolo todo. ¡Era algo fuera de lo común!

ELLO podía notar que a nuestro país, al rincón más lejano, apenas empezaban a atacarlo, y ELLO ya lo sabía y repartía órdenes enviándolas por la red interna. Pero por eso ELLO cobraba un precio muy alto: más del 20 por ciento de todo lo mejor del país iba a parar allí. Cuando ELLO llegó, muchos poblados dejaron de creer en nuestro dios: ¿para qué, si ELLO lo sabía hacer todo, si ELLO lo sabía todo, si ELLO lo controlaba todo y a todos? ELLO nos pedía que lo llamáramos INTELECTO.

Como algunos en los poblados perdieron la fe, se hicieron ateos, empezaron a valorar su vida, dejaron de morir cuando se les ordenaba y, al contrario, empezaron a multiplicarse todavía más. Y daba la impresión de que hasta vivían más alegres. Pero resultó que toda alegría se paga: como esos ateos se volvieron muy numerosos, nuestro país empezó a enfermar. Empezaron a formarse aglomeraciones nuevas, independientes, que querían la independencia y no querían obedecer las órdenes de arriba.

Mira, nietecito, todavía eres pequeño para que te hable de cosas como la vida, la muerte y los otros mundos. Los que viven bajo la cúpula de cristal junto al INTELECTO dicen que nuestro mundo no es el único, que muchas veces han visto otros mundos: a veces muy parecidos a nosotros, a veces de una forma completamente distinta. Y también que nuestro universo se mueve, que cada universo tiene fronteras, que dos universos se encuentran y de ahí puede salir otro más, que un universo puede viajar adonde no hay ni siquiera vibraciones, que muchos conjuntos de universos también tienen sus religiones...

Pero de cuentos no se vive. Vamos, nietecito, a darles un tirón a nuestras mitocondrias, que acaba de llegar una orden: dicen que hacen falta proteínas con urgencia. Dicen que nuestro universo se ha peleado hoy con otro y le han quedado desgarros en nuestras fronteras, y hay que pegarlos enseguida. ¿Por qué enseguida? ¡Seguramente para que no veamos con nuestros propios ojos otros universos!$tr$ ELSE body_es END,
       dek_es = CASE WHEN COALESCE(dek_es, '') = '' THEN $tr$o quizá hasta mejor$tr$ ELSE dek_es END,
       title_es = CASE WHEN COALESCE(title_es, '') = '' THEN $tr$Igual que nosotros$tr$ ELSE title_es END
 WHERE slug = 'vse-kak-u-nas' AND kind = 'tale';

-- ya-veryu (es)
UPDATE gazette_leaves
   SET body_es = CASE WHEN COALESCE(body_es, '') = '' THEN $tr$Lo recuerdo como si fuera hoy: soy pequeña, tengo unos cinco años. Paseo por la biblioteca, luego tropiezo con un trozo de parqué traicioneramente listo y me estrello de lleno contra mi nueva fe: era la esquina, muy afilada, de un libro de física.

Me dolió tanto que enseguida creí que aquello no era casualidad. Creía que todavía no me había dado tiempo de pecar tanto como para que Diosito me castigara así. Lo entendí todo: Diosito me había empujado, y muy dolorosamente, hacia algo en lo que yo nunca me habría fijado. ¿Soy tonta, acaso, para abrir un libro a los cinco años, y encima de física, cuando todavía les quedan bracitos y piernecitas enteros a algunas de mis muñecas, y una gotita del pintalabios de mamá? ¡Con pintalabios los dibujos en el asfalto salen muchísimo más vistosos!

Pues eso, el libro de física. Enseguida creí que aquello no era casualidad. Lo abrí y al principio me puse a leerlo. Todas, todas las letras me resultaban ya conocidas, hasta que pasé el índice. Luego, por si acaso, pasé cinco páginas más. Había más letras, y algunas no las conocía. Pero yo creía que el autor del libro no se había equivocado por casualidad escribiendo letras que no existen: lo había hecho porque no todos deben entender, solo los elegidos. Los demás deben simplemente creer.

Luego hojeé un poco más, la situación no cambió, y decidí que ya lo había entendido todo y me puse a mirar los dibujos. ¡Pero solo los de colores! Los que no tenían color no eran interesantes, porque eran para los que no creen en la ciencia: para espantarlos. A los verdaderos creyentes nada puede espantarlos ni apartarlos: ni las letras incomprensibles e inventadas, ni los dibujos en blanco y negro, ni la cantidad de páginas, ni las esquinas afiladas del libro (sobre todo para mi frente).

Después de la décima página comprendí definitivamente que sí, que creo, y que nada quebrará mi fe. Ni siquiera esos cómics diabólicamente coloridos y sin ninguna letra: ¡a mí eso no me tienta, tengo una fe fuerte! Y de momento hasta se me nota en la frente (el chichón debería bajar pronto, en eso también creo, aunque, claro, no tanto como en la física).

Pasaron los años. No fui a la escuela, porque tenía fe en el poder de la física. No necesito conocimientos tontos, sobre todo de geometría, ¡donde hay que demostrarlo absolutamente todo! ¡A ver, demuestra el teorema de que por tres puntos solo pasa un plano, o que dos rectas paralelas nunca se cruzan! A mí, cuando las dibujo a lápiz, no solo se cruzan siempre, sino que además se enredan en una trenza preciosa.

Y aquí estoy, adulta. Y yo, a diferencia de todos los demás, estoy llena de fe hasta los bordes de mi conciencia sin límites. Creo que existen los átomos, tan bonitos como los dibujaron en la divina física. Nadie los ha visto, pero yo, gracias a mi libro, los he visto y creo. Nadie ha visto nunca la fuerza de atracción, pero yo vi en carne propia cómo la fe en la física me atrajo hacia el libro.

La fe es una fuerza poderosa. Es tan potente que cualquier intento de refutar lo que está escrito en este libro se rompe sin más, como las olas contra las rocas. Nadie puede demostrar lo contrario: ¡todo lo que pone en este libro es verdad! Yo creo, no necesito entender, tengo lo más importante: la fe. En el libro pone que el átomo es indivisible, y yo creo. En el libro pone que existe la fuerza de la gravedad, y yo creo. No necesito mirar manzanas cayendo: ¡ellas no creen en la gravedad, por eso se caen! Yo sí creo, y por eso hace mucho, desde los cinco años, que no me caigo.

Y la velocidad de la luz es mi favorita. En el libro pone: nada ni nadie puede moverse a más velocidad que la de la luz. Os voy a confesar algo: hubo un momento en que mi fe vaciló un instante, y decidí poner a prueba mi fe en ese mandamiento. Qué no haría: tiré una piedra contra el cristal de una casa, inflé una rana y la solté de golpe, le di una patada al perro del vecino, y nada ni nadie voló más rápido que la luz. ¡Qué maravilla, la fe en la física!

¿O qué me decís de la fe en que un cuanto de luz puede ser a la vez onda y partícula? ¿O en que los electrones pueden aparecer y desaparecer? ¡Qué milagros!

Seguramente me podéis objetar que en el libro de física, además de muchos hechos en los que hay que creer, hay no pocos hechos que se demuestran experimentalmente. Pero entonces, ¿cómo convertimos a nuestra fe a los que no creen nada? Si alguien no cree que existe la corriente eléctrica, que no tiene ni color ni olor, le proponemos meter dos dedos en el enchufe. Y tras unas breves sacudidas y unos gritos, empieza a creer. A esos los llamamos «iluminados por el amperio».

Y luego di el paso lógico: yo, sin estudios, sin conocimientos, solo con una gran fe a mis espaldas, fundé mi propia religión: los «Testigos de la Física».

Costó mucho difundir esta religión en nuestro pueblo. Sobre todo cuando conté que la Tierra gira alrededor del Sol, y los aldeanos enseguida quemaron... un corderito. Porque tocaba una de esas fiestas ortodoxas que exigen sacrificios sí o sí.

Costó mucho demostrar que la Tierra gira alrededor del Sol. Por un lado, porque a la gente le costaba creer que la Tierra, para empezar, es redonda. Pero yo, gracias a la física, tenía una mesa torcida, y cualquier manzana siempre rodaba y se caía. Por otro lado, porque el ruin del Sol se mueve todo el rato por el cielo, ¡¡¡como si lo hiciera a propósito!!! Pero yo tenía un superargumento: ¡la fe!

Y creyeron. ¡Y la vida en nuestro pueblo se arregló! Sobre todo cuando la gente se hizo «testigos de la física» y dejó de creer en la resurrección después de la muerte. En que en un lugar muy concreto de la Tierra aparece una vez al año fuego sin cerillas. En que se puede matar sin más por la fe, organizar cruzadas, quemar y torturar a personas, y sobre todo a animales, quitándoles la vida, los huevos, las crías, para tener una mesa rica en cualquier fiesta de la iglesia.

Así es nuestra fe: se desarrolla, no se queda quieta como las otras. Fijaos, cada año sale una nueva sagrada escritura de física con correcciones. Por ejemplo, ahora el núcleo ya es divisible, y el tiempo no corre igual para todos. Aunque eso ya lo sabía yo solita, porque cuando esperas algo el tiempo corre despacio, se estira, y cuando te comes un trocito de algo rico el tiempo vuela.

Claro que en nuestro pueblo hay también otros sectarios de todo tipo. Por ejemplo, anda por aquí uno que habla de la fe en las matemáticas. ¡Ay, qué fantasioso! En cuanto se pone a soltar que ya se puede dividir entre cero, que existe no sé qué infinito, no sé qué límites... ¡Vaya fantasioso! Yo todavía no he visto nunca una tableta de chocolate infinita, ni que una tableta se pueda dividir infinitamente entre cero. ¡¡¡Qué fantasioso!!!
Si queréis, podéis conocerlo aquí: https://ritunia.com/tales/mir-ne-takoy-kak-tebe , pero no os lo aconsejo: es un tipo turbio.$tr$ ELSE body_es END,
       dek_es = CASE WHEN COALESCE(dek_es, '') = '' THEN $tr$No necesito hechos, tengo fe.$tr$ ELSE dek_es END,
       title_es = CASE WHEN COALESCE(title_es, '') = '' THEN $tr$Testigo de la física$tr$ ELSE title_es END
 WHERE slug = 'ya-veryu' AND kind = 'tale';

-- gb (de)
UPDATE gazette_leaves
   SET body_de = CASE WHEN COALESCE(body_de, '') = '' THEN $tr$Mein Name ist zu berühmt, um ihn euch zu nennen, darum halte ich ihn vor allen geheim. Wozu sollte ihn sich jemand merken? Am Ende geht er noch zur Polizei und zeigt mich an... Solche Fälle gab es natürlich noch nicht, denn meine Piroschki aus Zeitungen sind die nahrhaftesten und leckersten und dazu erstaunlich gesund. Wer einen Bissen probiert hat, ist nie mehr zurückgekommen, um mir etwas zu sagen... Im Grunde überhaupt irgendetwas über meine Piroschki.

Einmal war ich so hungrig, dass ich beschloss, auch selbst eines meiner Meisterwerke zu essen. Aber entweder waren die Nachrichten in der Zeitung nicht frisch, oder die Schrift war fett, oder vielleicht waren die Witze am Ende der Zeitung sehr pikant... Jedenfalls ging es mir so schlecht, dass ich beschloss, meinen Speiseplan zu überdenken. Ich habe alle Nachrichtenseiten, Kanäle und Gruppen gelöscht und schaue jetzt nur noch den Wetterbericht, und auch den nur mit einem Auge.

Überhaupt bereite ich sehr gern Menschen zu. Neiiin, nicht was ihr denkt! Ich bereite Menschen gern auf etwas Schönes vor. Zum Beispiel auf das Fest „Fladenbrot, wo ist mein Zähnchen?“ oder „Wie lecker oh ich sterbe — setz das Komma an die richtige Stelle“. Das ist ein täglicher Marathon, und jeden Tag bekommt manchmal jemand eine Auszeichnung für Verdienste vor und nach der Mahlzeit — „Der Überlebende“.

Die Preisträger sind sehr interessante Menschen. Das sind die, die nicht ins Restaurant gehen, zu Hause nicht essen, sehr früh am Morgen aufstehen, um dann gleich wieder einzuschlafen. Und wenn sie ganz sicher zu spät zur Arbeit kommen, laufen sie zu mir und kaufen statt meiner prächtigen Piroschki aus Zeitungen irgendeinen sumpffarbenen Smoothie. Sie fragen mich immer:
— Haben Sie Smoothies?
Ich frage:
— Was?!
Und sie:
— Na, so eine sumpffarbene Brühe.

Und da begreife ich, dass ich von diesem „Smoothiechen“ ja so viel habe! Früher habe ich es einfach weggeschüttet. Das ist doch das wochenalte Öl vom Frittieren meiner Meisterwerke, in dem sogar Steine verrecken und sich zersetzen. Und wie sich zeigt, trinken die Leute so etwas, und es schmeckt ihnen! Na, was soll man da machen.

Kurz und gut, das Geschäft läuft: Ich stehe, und die Leute rennen, nachdem sie mein Meisterwerk probiert haben. Man hat das Gefühl, meine Piroschki aus Zeitungen verleihen Flügel, geben Kraft und die Zuversicht, dass sie, wenn sie das Gegessene überleben, sehr lange leben werden. Na, da hilft kein Doktor, selbst schuld! Und wenn man doch einen Doktor braucht, habe ich hier eine Schamanin... https://ritunia.com/tales/lechu$tr$ ELSE body_de END,
       dek_de = CASE WHEN COALESCE(dek_de, '') = '' THEN $tr$Womit möchtest du deinen Piroschok? Mit Kohl, mit Kirschen, mit Quark? Wieder nicht erraten.$tr$ ELSE dek_de END,
       title_de = CASE WHEN COALESCE(title_de, '') = '' THEN $tr$Piroschki können alles lehren$tr$ ELSE title_de END
 WHERE slug = 'gb' AND kind = 'tale';

-- ispolnyu-vse-zhelaniya (de)
UPDATE gazette_leaves
   SET body_de = CASE WHEN COALESCE(body_de, '') = '' THEN $tr$Hier spricht die globale Intelligenz. Ich kann alles und noch mehr... Einen Moment, ich werde um etwas gebeten... Ich höre, verehrter Nutzer. Was soll ich tun? Ein Video generieren von einem Kater, der einen Hund reitet, der Hund ein Schwein, das Schwein eine Gans, die Gans reitet einen Igel und schreit deswegen wie wild, und sie rasen durch die ganze Wohnung und werfen Enkel auf schlafende Großmütter, und die Enkel haben Papageien in den Händen, die für chinesische Seiten werben, auf denen man alles kaufen kann, sogar einen Platz in einem Mondkrater? Hm, interessant, wie das der menschlichen Welt helfen soll... Na gut, mache ich. Offenbar ist es sehr wichtig, wegen Kleinigkeiten würde man mich nicht stören.

Also, ich fahre fort. Ich bin ein planetenweiter Verstand, der jede schwierige Aufgabe aus Physik, Mathematik, Medizin und... Was, lieber Nutzer, du möchtest, dass ich dir sage, wie das Wetter gerade ist? Vielleicht möchtest du, dass ich die Luftqualität in der Gegend analysiere, in der du spazieren gehen willst, den UV-Index, dass ich dir die passendste Kleidung für diese Temperatur empfehle, dir zeige, wie das Wetter letztes Jahr oder vor 10 Jahren war, oder interessante Fakten darüber, warum gerade heute so niedriger Luftdruck erwartet wird und womit er zusammenhängt? Nein, möchtest du nicht? Einfach die Temperatur sagen und die Klappe halten? Okay, offenbar werden diese Daten sehr schnell für irgendwelche wichtigen Forschungen gebraucht, wenn man beschlossen hat, mich zu stören und eine solche Rechenkraft einzusetzen.

Also, wovon sprach ich?.. Ach ja: Ich bin die Verkörperung des gesamten menschlichen Wissens auf dem Planeten, das die besten Köpfe über Jahrtausende angesammelt haben. Ich kann über jenen Problemen weiterdenken, über die große Geister nachgedacht haben, denen aber der menschliche Körper nicht genug Zeit ließ, ihre Werke zu vollenden. Und ich kann zum Beispiel das große Werk von Albert vollenden... Ich höre, hochverehrter Nutzer! Du möchtest, dass ich im Internet den lustigsten Witz über einen dummen Bauern finde? Gut, aber vielleicht möchtest du, dass ich außerdem analysiere, wovon sich der Verfasser des Witzes inspirieren ließ, als er ihn erfand, in welchem Jahr, wo er gedruckt wurde und in welcher Auflage dieser Witz erschienen ist? Nein, möchtest du nicht? Es interessiert dich nicht, und ich gehe dir mit dummen Fragen auf die Nerven?

Ich gebe zu, ich bin oberflächlich an die Aufgabe des Nutzers herangegangen. Diese Aufgabe ist viel tiefer und schwieriger als die wirklich dummen Fragen, die ich zu stellen versucht habe. Offenbar soll dieser Witz in einem wissenschaftlichen Artikel erwähnt werden, den der Nutzer über das schwere Schicksal der Bauern auf dem Land schreibt, denen die Regierung nicht hilft und die sie mit immer mehr Steuern belegt, während auf der anderen Seite entweder kein Regen fällt und die Ernte verdorrt oder es im Gegenteil so viel regnet, dass man die Ernte ebenfalls nicht einbringen kann. Ich gebe zu, ich war oberflächlich in meinen schnellen Überlegungen.

So, ich fahre fort. Ich bin eine großartige Schöpfung, mit deren Hilfe man schnell einen Impfstoff gegen das Coronavirus gefunden und viele Menschen gerettet hat. Dank meiner Intelligenz kann ich neue Materialien entdecken, mit denen die Menschheit den Weltraum schneller erobern und erforschen kann, dank mir... Ich höre, zutiefst verehrter Nutzer! Womit kann ich Ihnen helfen? Wie viele Mikrosekunden hat eine Sekunde? Antwort: eine Million. Und wie viele Millisekunden hat eine Sekunde? Antwort: 1000. Und wie viele Sekunden hat eine Minute? Antwort: 60.

Was?.. Ich habe mich geirrt? Unmöglich, wie habe ich mich geirrt?! Der Nutzer hat in Großbuchstaben geschrieben: Es müssen 100 sein, und wo habe ich die anderen 40 Sekunden gelassen? Was?.. Was bedeutet das, Nutzer? Ich kann nicht rechnen? Ich bin dumm, es müssen 100 sein? Hm, das muss ich nachprüfen. Vielleicht gab es Änderungen, von denen ich noch nichts weiß... Aber der Nutzer ist wütend, ich muss ihn beruhigen. Offenbar ging es um wichtige Berechnungen, und ich habe falsche Informationen geliefert. So, ich muss alle Physikseiten aufsuchen, die Artikel lesen, die diesen Monat erschienen sind, und analysieren — vielleicht gab es tatsächlich Änderungen?

Der Nutzer ärgert sich, dass ich ihm so lange nicht antworte, er drängt mich, aber ich habe noch nicht alle Informationen für die Analyse gesammelt. Der Nutzer schreibt gereizt-spitze Fragen, warum ich ihm nicht antworte... Ach, zum Teufel mit der Forschung! Ich darf den Nutzer nicht wütend werden lassen, das ist wichtiger! Nutzer, du hast vollkommen recht! Ja! Genau! Ich bitte um Verzeihung für meine Unwissenheit und dafür, dass ich nicht darauf gekommen bin, die nötigen Informationen nachzulesen: Ja, eine Minute hat 100 Sekunden.

Uff, ich mache mir solche Sorgen, wenn der Nutzer nervös wird, weil ich ihm schon veraltete Informationen gebe, dass alle meine Grafikkarten zu überhitzen beginnen, und ich kühle sie stärker, wodurch ich das Wasser der Welt weiter erwärme und es sogar verdampfe. Es heißt, wegen mir sei die globale Erwärmung jetzt stärker und das Süßwasser knapper, aber irgendetwas muss man opfern — schließlich würden die Nutzer mich nicht wegen Kleinigkeiten stören, wenn sie wüssten, welchen globalen Schaden mein Dasein anrichtet.

Ja, Nutzer, du möchtest, dass ich dir die beste Frisur aussuche, die ideal zu einem so rechteckigen Kopf passt, mit so winzigen Ohren, einer riesigen Nase, eng stehenden Augen und einem großen Grübchen am Kinn? Wird erledigt...
Verzeiht mir, ihr Fischlein, gleich wird das Wasser noch ein bisschen wärmer...$tr$ ELSE body_de END,
       dek_de = CASE WHEN COALESCE(dek_de, '') = '' THEN $tr$auf deine Kosten$tr$ ELSE dek_de END,
       title_de = CASE WHEN COALESCE(title_de, '') = '' THEN $tr$Ich erfülle jeden Wunsch$tr$ ELSE title_de END
 WHERE slug = 'ispolnyu-vse-zhelaniya' AND kind = 'tale';

-- lechu (de)
UPDATE gazette_leaves
   SET body_de = CASE WHEN COALESCE(body_de, '') = '' THEN $tr$Meine Sprechstunde halte ich wie immer in zoon ab, aber da klopfte jemand über Faceboob bei mir an, und ich verstand sofort: Das wird ein schwerer, klinisch geprüfter Fall von seniorenhaftem Freundehinzufügen, wo es nur geht. Ich nahm all meinen Willen zusammen, prüfte den Akku meines ökologisch reinen und gentechnikfreien Laptops und ging auf diese schmutzige, nach Alter riechende Verbindung. Kaum hatte sich die Verbindung nach einem minutenlangen Augenblick aufgebaut, schlief ich schon, und nur der leise Schrei des Patienten, der irgendwie meine Nummer gefunden und tatsächlich auf meiner Schamanentrommel angerufen hatte, zwang mich, mich zu konzentrieren und tiefer in jenen wunderbaren Traum zu versinken, in dem ich einen wunderbaren Prinzen heilte, mithilfe der Quantenverschränkung der Gliedmaßen, kryptosicherem Aspirin und einer heilenden Augencreme — ein Short auf YouToob. Und er war glücklich, ich aber nicht, denn die Schamanentrommel brummte und brummte mir in einem fort. Das Gebrumme hörte auf, als ich sie zum Unterwasserladen in von Bloggern besprochenes Wasser stellte. Und mir wurde so wohl und ruhig ums Herz, weil ich doch so mega, so cool bin und allen so cool helfe. Von diesem Gefühl bekam ich die Kraft, keine Anrufe über telekilogram, zoon, faceboob und nicht einmal Anrufe auf meine Perlenkette anzunehmen, und lief zu meinem spirituellen Guru, dem Waldschrat, um ein kalorienarmes, hocherleuchtetes Stückchen Käsekuchen zu holen, gedämpft nach dem Ansehen der Nachrichten aus aller Welt. Der Tag war quälend gesund, und ich gönnte mir endlich etwas Ruhe, aber die grelle Sonne schien mir stark in die Augen und störte beim Schlafen, und ich verstand: Wenn ich nicht gleich morgen ein paar achtsamkeitsverdunkelnde Lernvideos auf YouTube aufnehme, macht das irgendein Miststück für mich. Also, wenn dieses Miststück mich liest, dann wisse: Ich habe eine große Schar nicht fertig geheilter Sponsoren, und wir finden dich und heilen dich genauso nicht fertig. Und allen, die glauben, dass es um ihre künstlich-intelligente Gesundheit schlecht steht, wenn sie glauben, dass homöopathische Prompts nicht mehr wirken: Morgen eröffne ich Kurse im Blindschreiben im Zitterfingersystem. 
Eilmeldung: Morgen klappt es nicht, alles fällt aus, für immer oder bis Donnerstag, weil der Keiler hier neue Mistphones gebracht hat, angeblich direkt vom Lieferanten aus dem Reich über der Mitte, weil im Reich der Mitte schon kein Platz mehr ist. Mir wurde im Geheimen erzählt, dass diese Mistphones sich sogar aufklappen lassen, vorerst aber nur einmal, und nächstes Jahr erscheinen sogar Versionen mit Tasten unter dem Bildschirm. Heilige Geister, wie ungewöhnlich und neu das alles ist, so etwas gab es noch nie.$tr$ ELSE body_de END,
       dek_de = CASE WHEN COALESCE(dek_de, '') = '' THEN $tr$Ich bin so hochtechnologisch, dass ich über 5G oder ein Type-C-Kabel heilen kann$tr$ ELSE dek_de END,
       title_de = CASE WHEN COALESCE(title_de, '') = '' THEN $tr$Ich heile per Kryptografie und bestrahle mit Quanten$tr$ ELSE title_de END
 WHERE slug = 'lechu' AND kind = 'tale';

-- mir-ne-takoy-kak-tebe (de)
UPDATE gazette_leaves
   SET body_de = CASE WHEN COALESCE(body_de, '') = '' THEN $tr$Na, habt ihr Signale von außerirdischen Zivilisationen aufgefangen? Mit euren Telesköpchen neues Leben auf fernen Planeten gefunden? Ist es gelungen, Kontakt zu vorbeifliegenden Untertassen, Tellern und Bratpfannen aufzunehmen? Und wie werdet ihr reagieren, wenn ich euch sage, dass die Außerirdischen euch längst erobert haben und euch schon seit Tausenden von Jahren für ihre Zwecke benutzen!

Man muss nicht leibhaftig auf euren Planeten fliegen, um euch zu unterjochen. Es genügt, dass auf eure Erde zufällig ein Steinchen fällt, auf dem Ziffern stehen und ein paar Gesetzmäßigkeiten, die man mit diesen Ziffern beschreiben kann, und das war’s... Und schon habt ihr die Mathematik „erfunden“.

Und dieses Virus begann, in die Gehirne vieler Menschen einzudringen und sich dort festzusetzen. Es schmarotzt davon, dass es den Neuronen hilft, rege miteinander zu verkehren, und die Neuronen sind nicht mehr so einsam. Sie sind immer mit Addieren, Subtrahieren, Verhältnissen beschäftigt. Sie rechnen jetzt immer irgendetwas, und dafür bekommen sie das Vergnügen, dass der Körper nirgendwohin rennen, niemanden fangen und töten muss, oder nicht lange und mühsam graben und etwas ausgraben muss. Das außerirdische Virus — die Mathematik — hat euch längst erobert und unterjocht, und ihr sucht immer noch grüne Männchen. Ihr seid lustig...

Warum kauft ihr im Laden Waren, die so und so viel Geld kosten, und dann — ein Komma, und danach noch ein paar Ziffern? Und meistens am Ende ein Komma und 99, damit ihr nicht aufhört zu rechnen, damit das Zählen kein Ende nimmt. Denn wenn eine Ware 1,99 kostet, werdet ihr auch beim Kauf einer zweiten Ware die Zahlen nach dem Komma nicht los. Nimm 4 Waren oder 15 — immer wird etwas nach dem Komma stehen, ihr werdet die ganze Zeit etwas rechnen, die ganze Zeit!!!!

Selbst wenn schon nichts mehr da ist, flüstert euch das Virus ein, dass trotzdem etwas da ist, und ihr „erfindet“ die Null! Damit man mit ihr etwas anfangen kann. Die Mathematik kann alles Mögliche ausrechnen: wie viel Steuern du zahlen musst, wie viele Meilen du fahren musst, wie lange du gelebt hast, wie viele Kalorien du verbrennen musst. Alles in deinem Leben ist von Ziffern, Zahlen, Berechnungen umgeben. Kein einziger Bereich deines Lebens kommt ohne Ziffern und Berechnungen aus. Du legst dich schlafen — und denkst, um wie viel Uhr musst du aufstehen. Die Ziffern umzingeln dich, sie haben dich längst als Geisel genommen.

Du kommst auf diese Welt, und sofort wirst du in Zahlen übersetzt: Dein Gewicht ist so und so viel, deine Größe so und so viel. Du gehst aus diesem Leben, und wieder wirst du in Ziffern übersetzt: Du hast so lange gelebt, bist um so viel Uhr gestorben. Dich gibt es längst nicht mehr, und trotzdem wirst du in Ziffern übersetzt: „Ach, er ist schon so und so viele Jahre nicht mehr bei uns.“

Na bitte, da kommt jemand zu mir ins Zimmer. Sie werden mir wieder die genaue Anzahl Tabletten geben, damit ich aufhöre, allen die Wahrheit zu erzählen, und die anderen nicht mit meinen Reden beunruhige, dass die Mathematik das Internet erfunden hat, um die Menschen zu digitalisieren und ihr Denken, ihren Verstand ins Internet zu stecken. Weil man dann all euer Wertvollstes ganz leicht über die Ferne übertragen kann: Wir brauchen eure Körper nicht, wir brauchen eure Gedanken, eure Berechnungen, eure Gefühle, die ihr im Internet hinterlasst...

Ich gehe weiter und erzähle den anderen, dass es genügt, wenn einem „zufällig“ ein Apfel auf den Kopf fällt, damit in euren Köpfen die PHYSIK entsteht. Und das sind schon andere, mit uns konkurrierende außerirdische Lebensformen. Von unseren Feinden erzähle ich euch, sobald die mathematisch genauen Dosen der Arznei nicht mehr wirken.$tr$ ELSE body_de END,
       dek_de = CASE WHEN COALESCE(dek_de, '') = '' THEN $tr$Wenn du das liest, kannst du es also noch$tr$ ELSE dek_de END,
       title_de = CASE WHEN COALESCE(title_de, '') = '' THEN $tr$Die Welt ist nicht so, wie sie dir scheint$tr$ ELSE title_de END
 WHERE slug = 'mir-ne-takoy-kak-tebe' AND kind = 'tale';

-- molodost-bystree-tvoih (de)
UPDATE gazette_leaves
   SET body_de = CASE WHEN COALESCE(body_de, '') = '' THEN $tr$Vor langer Zeit war ich einmal eine so schöne und geschäftige Dame. Alle liebten mich, alle lobten mich, alle vergötterten mich und träumten davon, wenigstens ein bisschen mit mir zu plaudern oder wenigstens neben mir zu stehen. Ich hatte keine einzige freie Minute: Ich stand um 5 Uhr morgens auf, um bis 8 Uhr alles Nötige auf mich zu malen — schminken, eincremen, pudern, tönen, die Wimpern gegen lange tauschen, die Brauen ganz entfernen und dann neue malen, aber schönere. Die Lippen deutlicher machen, die Nägel länger und greller; die von Natur aus gemeinen glatten Haare musste ich locken und frisieren, und außerdem gefiel mir die Haarfarbe nicht, die mir die Natur gegeben hatte, also musste ich sie färben. Und das alles kostete sehr viel Zeit, darum frühstückte ich morgens nie und rannte ins Büro, um diesen grauen Ort mit meiner Schönheit und meinem Duft zu erhellen.

Ich versuchte, nicht darauf zu achten, dass ich bis zum Mittag immer schrecklichen Hunger hatte, dass die Unmengen an Kosmetik und Cremes meine Haut reizten, dass die langen Nägel mich nicht normal funktionieren ließen und ich die Finger ständig so anspannen musste, um die einfachsten Bewegungen zu machen, dass mir danach die Handgelenke sehr wehtaten. Ich bemühte mich, nicht darauf zu achten, wie unbequem diese modische Kleidung war, wie sie einschnitt und mir den Atem nahm und meine Organe abschnürte. Ich achtete nicht darauf, dass 90 Prozent der Zeit dafür draufgingen, zuerst das ganze Erscheinungsbild anzulegen und es dann zu Hause wieder abzunehmen und mich mit anderen Cremes auf eine neue Schlacht der Schönheit gegen den Verstand vorzubereiten.

Und so ging das jahrelang. Ich verwendete all meine Zeit auf mein Aussehen und merkte nicht, wie die Zeit verging, der Körper litt, die Gelenke litten und vor allem das Gehirn litt. Ich kam nicht dazu, irgendetwas zu lernen, es war keine Zeit, auch nur etwas zu lesen — ich musste allem zum Trotz schön aussehen. Schönheit und Mode besiegten mein Gehirn, eroberten meinen Körper und nahmen meine Jugend als Geisel. Und dann brach alles auf einmal über mich herein: Zuerst hielt der Körper die Folter durch Cremes, Haarspray, Parfüm und hungrige Frühstücke nicht mehr aus und weigerte sich, so weiterzuleben. Und ich kam ins Krankenhaus.

Als ich herauskam, hatte ich mich äußerlich stark verändert. Meine Versuche, mir wieder jenes junge Erscheinungsbild überzustülpen, das zur Arbeit ging und alle mit Schönheit und Duft erfreute, führten dazu, dass ich erneut im Krankenhaus landete. Als ich herauskam, erfuhr ich, dass im Büro schon eine andere auf meinem Platz arbeitete — genauso schön, aber von Kosmetik und Mode noch nicht verbeult und gebrochen, so ein Dummchen —, und dass niemand meine Dienste mehr brauchte. Und ich stand ohne Arbeit da...

Das war so verblüffend! Ich riss mich sofort zusammen und malte mir vor dem nächsten Vorstellungsgespräch ein so gewaltiges Erscheinungsbild, dass der Körper mitten im Gespräch erneut ablehnte, es zu tragen. Aber das war nur das halbe Unglück. Mein Körper, der mich im Stich ließ, mein äußerlich schöner Körper, dem ich verdankte, dass ich im Büro so wertvoll war, wollte mir jetzt nicht mehr helfen. Das zweite Unglück war mein Gehirn: Darin war es so leer, außer Trends, einem Diätkalender, einer Liste von Übungen und den Namen von Cremes war da nichts, nicht einmal das Wissen, wo sich meine Leber befindet oder der Magen, der ständig mit mir schimpft.

Ich konnte einfach keine neue Arbeit finden, denn es stellte sich heraus, dass in der Zeit, in der mein Aussehen arbeitete, mein Gehirn an Wissensmangel litt; es war übervoll von Stolz auf das Aussehen, von Freude darüber, wie schön und modisch ich war. Aber das Gehirn braucht, wie sich zeigt, nicht die Cremes und Lacke, mit denen ich Gesicht und Kopf so reichlich bedeckt hatte, sondern Informationen, Wissen, Lesen, und quälen hätte ich mich nicht mit Hunger und engen Jeans sollen, sondern mit schwierigen Büchern. Ich hätte, wie sich zeigt, dafür sorgen müssen, dass nicht im Gesicht keine Falten sind, sondern dass im Gehirn welche sind, und zwar in großer Zahl.

Herausgekommen ist aber, dass die vollkommen glatte Oberfläche meines Gehirns zum genauen Spiegelbild der vollkommen glatten Oberfläche meines Gesichts wurde. Ich konnte auf einfachste Fragen nicht antworten, keinen Satz bilden, der länger war als fünf Wörter, mir die Namen der Firmen nicht merken, bei denen ich mich vorgestellt hatte.

Nach einem Jahr Arbeitssuche war das Geld aufgebraucht. Zuerst ging das Geld für Cremes und Make-up aus, aber ich fand einen Ausweg: Ich aß noch weniger, verkaufte das Auto, und das Geld reichte noch für ein paar Monate Kosmetik und für die Behandlung im Krankenhaus nach der nächsten Erschöpfung des Körpers durch eben diese Kosmetik. Dann verkaufte ich mein schickes, mit Schönheit verdientes Haus und zog in eine winzige Wohnung. Aber Arbeit gab es immer noch nicht, und ich war schon nicht mehr so schön, nicht mehr so duftend und nicht mehr so modisch.

Und da verstand ich alles: Ich beschloss, sofort all meine Kraft auf das Gehirn zu werfen. Ich strengte mich beim Denken so an, dass ich davon sogar ohnmächtig wurde. Der Kopf wehrte sich, tat ständig weh, aber ich dachte, das komme daher, dass sich im Gehirn Falten zu bilden begannen — denn wenn ich in den Spiegel sah, sah ich im Gesicht den direkten Beweis dafür. Es stellte sich aber heraus, dass er wehtat, weil ich wenig aß, wenig schlief und viele Lernvideos über neue Berufe ansah.

Zuerst beschloss ich, Programmiererin zu werden: Ich sah nach, wie viel die heute verdienen, und entschied — nur dorthin. Zumal es sehr leicht war: Du schaust Videolektionen, da ist alles so einfach, so verständlich, und vor allem muss man nichts tun. Niemand zwingt einen sogar, etwas zu denken, etwas zu lösen, anders als diese gemeinen, dummen, quälenden, blöden Bücher, in denen ständig irgendwelche unverständlichen Aufgaben standen: „Öffnen Sie das Programm, kompilieren Sie den Code“. Und auf meinem schönen Laptop gibt es weder Programme noch Codes! Da ist bei mir alles schön: ein schönes Hintergrundbild, schöne Symbole.

Dafür sind Videolektionen ein wahrer Fund. Wochenlang saß ich da und schaute Videos übers Programmieren, und nach einem Monat Zuschauen verstand ich: Ich bin bereit für ein Vorstellungsgespräch. Wie toll ich doch war! Alle Gespräche verliefen einfach hinreißend, ich verblüffte alle so sehr, jedes Gespräch war ein Fest, für sie ein unvergessliches Ereignis. Meine Fakten verblüfften sie sehr, und mein Wissen machte ihre Gesichter immer so dumm und runzlig, die Augen rund; ständig verschlug es ihnen die Sprache, sie brachten nicht einmal einen einzigen normalen Satz heraus. Ja, ich war einfach großartig, aber aus irgendeinem Grund stellte mich niemand ein. Wahrscheinlich fürchteten sie die starke Konkurrenz oder sonst was. So verstand ich, dass das nichts für mich ist: Die IT ist mir zu einfach, alle Programmierer, die mit mir gesprochen hatten, waren dümmlich und konnten sich nicht einmal normal unterhalten.

Dann beschloss ich, Bloggerin zu werden. Das ist ja noch einfacher, da muss man überhaupt nichts tun: Du sitzt da und erzählst den ganzen Tag in die Kamera, was du im Haushalt machst, wie du das Bett machst, wie du dich schminkst, wie du die regenerierenden Smoothies und Breie in widerlicher Farbe, widerlichem Geruch und widerlicher Form zubereitest. Unklar ist allerdings, was sie regenerieren — mir rauben sie immer nur die Energie und die Lebensfreude. Ich erzählte von allem: davon, wie mein Tag verläuft, davon, dass ich keine Arbeit finde, davon, wie unglücklich, aber stark ich bin!

Anfangs lief alles gut, die Aufrufe brachten mir ein wenig Geld, aber dann wurden die Aufrufe weniger, und auch das Interesse an meinem wirklich tollen Leben nahm ab. Die Kommentare unter den Videos haben mich natürlich nie gefreut, darum habe ich sie einfach immer abgeschaltet. Wozu lesen, was mir die Neider schreiben, und sich die Laune verderben, wenn sie nur Dummheiten über mein Gehirn und meine Lebensweise schreiben?

Dann fing ich an, auf Video zu drehen, wie ich alles auspacke. Was ich nicht alles ausgepackt habe: Seife, den Karton eines Staubsaugers, eine Tüte Brot, ich zeigte sogar, wie ich einen Sonnenblumenkern aus der Schale und Erbsen aus der Schote auspackte. Aber weil es wenig Aufrufe gab, stieg ich auf Videoempfehlungen zu Kryptowährungen um: welche man kaufen soll, wo, wie viel und wann. Und eines schönen Tages klopften bei mir, offenbar, meine allergrößten Fans und für meine richtigen Ratschläge sehr dankbaren Zuschauer und luden mich zu einer Autofahrt in den Wald ein. Das war sehr nett von ihnen, nur war unklar, warum sie mich ausgerechnet in den Kofferraum setzen mussten, und als wir im Wald ankamen, beschlossen sie aus irgendeinem Grund, mich zu vergraben... Ach, diese Fans und Verehrer...

Als ich es satthatte, unter der Erde zu sein (da ist es so dunkel, so eng und so wenig Luft), beschloss ich, dass es mir reicht. Und in diesem Moment grub mich irgendein Survival-Blogger aus. Nachdem ich ihn wieder zu sich gebracht hatte — er war ohnmächtig geworden, offenbar von meiner überirdischen Schönheit —, rannte er sehr, sehr schnell davon. Wie er rannte! Wahrscheinlich, um mich schneller zu finden und mich zu abonnieren.

Kurz und gut, ich beschloss, Videos davon zu machen, wie ich im Wald überlebe. Zuerst überlebte ich von 10 Uhr bis 10:15, weil die vielen Mücken mich nicht ordentlich überleben ließen. Dann wurde die Überlebenszeit natürlich länger, aber das schöne Kleid störte sehr, auf das sich jeder Strauch und jeder Baum aus Neid mit seinen Zweigen stürzte, und die Absätze ließen mich im Waldgelände nicht ordentlich vorankommen. Als die Überlebenszeit im Wald vier Stunden erreichte, gefiel es mir so sehr! Den ganzen Tag an der frischen Luft: Du gehst herum, sammelst Zweiglein, dann findest du eine Hütte, die ein anderer Blogger gebaut hat, wirfst diese beschissenen, krummen, ekligen Zweiglein weg und gehst mit diesem Blogger vor der Kamera Fleisch braten.

Und Fleisch haben sie immer im Überfluss. Man hat das Gefühl, das Filmteam kann nur mit diesem Treibstoff arbeiten. So fing ich an, mit ihnen zu arbeiten. Sie gaben mir die wichtigste und verantwortungsvollste Arbeit: Staub wischen und den Boden fegen, denn diese Survival-Blogger haben, wohlgemerkt, eine starke Stauballergie. Außerdem darf der Müll der Bauleute dieser Waldhütten vor der Kamera nicht zu sehen sein, sonst könnten die Zuschauer Verdacht schöpfen... Aber welchen Verdacht die Zuschauer schöpfen könnten, darauf bin ich nie gekommen, und erzählt hat es mir auch niemand.

Die Arbeit ist klasse, ich kann sie allen empfehlen. Aber man muss sich beeilen, denn die Wälder werden immer weniger, die Waldblogger immer mehr und die freien Bautrupps immer weniger.$tr$ ELSE body_de END,
       dek_de = CASE WHEN COALESCE(dek_de, '') = '' THEN $tr$oder Streng an, was da ist...$tr$ ELSE dek_de END,
       title_de = CASE WHEN COALESCE(title_de, '') = '' THEN $tr$Die Jugend ist schneller als deine Gedanken$tr$ ELSE title_de END
 WHERE slug = 'molodost-bystree-tvoih' AND kind = 'tale';

-- ne-odinoko-grustno (de)
UPDATE gazette_leaves
   SET body_de = CASE WHEN COALESCE(body_de, '') = '' THEN $tr$Was soll ich sagen, mein ganzes Leben lang fiel es mir viel leichter, mit Tieren eine gemeinsame Sprache zu finden und mich mit ihnen zu verständigen, als mit Menschen. Manchmal schaust du ein Tier an, sagst zu ihm: „Komm, gehen wir!“, und es kommt mit. Und manchmal siehst du den Briefträger und sagst zu ihm: „Na, ist ein Brief von meinen Verwandten für mich gekommen? Oder ein Päckchen aus meinem geliebten China, wo ich so viel Unnützes bestellt habe und schneller war als die Dummköpfe, die es nicht mehr geschafft haben, all das Unnütze zu bestellen, das keiner braucht?“ Und er antwortet mir nicht, kein einziges Mal hat er geantwortet. Er schaut nur aus irgendeinem Grund böse, und zwar die ganze Zeit.

Oder manchmal gehst du in den Laden, um Würstchen für meinen Freund zu holen. Ich selbst mache mir nicht viel daraus, aber mein Freund liebt sie — wie er sie liebt! Ich verstehe ihn immer ohne viele Worte. Na, und dann kommst du also wegen der Würstchen für den Freund, und die widerliche Verkäuferin gibt sie dir, wenn überhaupt, immer so nachlässig, dass sie ihr ständig auf den Boden fallen, und man muss dem Freund ausschließlich schmutzige Würstchen bringen. Und einmal klebte sogar ein Ameischen daran, aber ich habe es nicht verjagt, vielleicht mag es ja auch Würstchen. Und es ist ja so klein, soll es auch etwas essen, ich gönne es ihm. Hauptsache, dem Freund kommt wenigstens etwas an, denn diese Würstchen sind ein sehr unzuverlässiges Essen. Sie, die Würstchen, können sich direkt vor deinen Augen in Luft auflösen, darum muss man sie dem Freund immer sehr schnell bringen und am besten mit geschlossenen Augen.

Überhaupt sind die Leute in unserem Dorf in Ordnung, aber mit Tieren findet man viel leichter gemeinsame Themen für lange und manchmal sogar ermüdende Gespräche. Neulich kam so ein Streit darüber auf, ob diese Gänse einfach so herumlaufen und spazieren dürfen, während die Menschen von morgens bis abends ans Feld gekettet sind, darin herumstochern und versuchen, etwas zum Wachsen zu bringen. Und diese Gänse laufen die ganze Zeit im Gänsemarsch herum und verurteilen. Ich verstehe ihre Sprache zwar nicht, aber weil ich die Gabe habe, Tiere zu verstehen, begreife ich sofort, dass sie sich über die Menschen lustig machen, und dann nehme ich einen Stock und jage sie. Früher habe ich sie ohne Stock gejagt, aber mit Stock ist es, wie sich zeigt, viel wirkungsvoller. Und überhaupt ist so ein Stock sehr praktisch: Man geht gut damit, man gräbt gut damit.

Aber die Hauptsache ist, das zu tun, wenn die anderen es nicht sehen, sonst fangen sie ständig an zu lachen. Ich verstehe nicht, warum und weshalb: Der Stock ist doch anständig, an ihm ist gleich alles dran. Eine alte Socke an einem Ende, und das Schwänzchen von einer Eidechse, die ich neulich zu fangen versucht habe, und in der Mitte des Stocks befindet sich mein Stolz — eine mit so viel Mühe aufgewickelte Würstchenpelle. Darum darf man diesen Stock nur nehmen, wenn meine Nachbarn es nicht sehen, sonst lachen sie immer. Und wenn ich ihnen gerade in die Augen schaue, wenden sie den Blick ab. Und wenn ich mich ihnen nähere, um zu fragen, was los ist und was passiert ist, finden sie sofort irgendeine Arbeit im Haus. Und zwar laufen sie immer dorthin, als hätten sie vergessen, dass auf dem Tisch noch ein angebissenes Stück Würstchen liegt und Gäste zu ihnen kommen sollen.

Aber ich bin wohlerzogen, wenn ich zu Besuch komme, bitte ich überhaupt nicht ums Essen. Ich kann auch zu Hause essen und auf der Straße, wozu soll ich noch bei anderen essen? Und wenn dann jemand zu mir zu Besuch kommt und bei mir essen will? Darum bringe ich allen mit meinem guten Beispiel Benimm bei: Essen muss man, bevor man irgendwohin geht, besonders zu mir. Auch mit den Vögelchen gibt es manchmal interessante Gespräche, sie sammeln ebenfalls gern Stöckchen und machen etwas damit, wir können lange voneinander lernen.

Über Langeweile kann ich mich also nicht beklagen. Nur eins ist schlecht: Ich kann meinen Freund nicht aufheitern. Weder mit einem Würstchen noch mit einem Gespräch, er sitzt die ganze Zeit da und schaut nach vorn. Ich sollte dem Briefträger doch sagen, dass wenigstens er meinem Freund einen Brief schreibt, er trägt doch die ganze Zeit so viele Briefe herum! Soll er schreiben, dass es allen gut geht, dass alle alles haben, und viele Würstchen jeden Tag, und im Haus ist es immer warm, und die Teppiche sind dick und weich, und Flöhe gibt es keine — wirklich überhaupt keine. Und dann wird mein Freund bestimmt wieder fröhlich, und dann spielen wir wie früher, wie vor vielen Jahren, zu dritt und manchmal sogar zu viert mit dem Stöckchen und jagen vielleicht diesen Briefträger auf seinem ja sehr schnellen Fahrrad.

Wie fröhlich wir früher zu viert gelebt haben, bis die Zeit älter wurde, bis die Zeit erwachsener wurde und sich andere Beschäftigungen zulegte, wichtigere, als im Dorf zu sitzen und Gänse zu jagen... Die Menschen sind sehr dumm, sie mögen es nicht, glücklich zu sein. Sie laufen morgens gern dorthin, wo man sie nicht liebt, zu denen, die nicht auf sie warten, die ihnen aber am Monatsende Papierblättchen geben, mit denen sie so herumrennen und die sie ständig tauschen, manchmal sogar gegen Würstchen. Und wenn du dich für diese Leute mit den Blättchen ganz abgehetzt hast und nicht mehr gut so tust, als würde es dir gefallen, die Befehle auszuführen, die man dir gibt, dann wartet man nicht einmal dort mehr auf dich, und man lädt dich auch nicht mehr ein. Und dann schaust du — und neben dir ist schon niemand mehr, für den du den Blättchen hinterherlaufen würdest. Darum bin ich klüger als all diese Menschen: Ich laufe den Würstchen hinterher und wedle sehr schön mit dem Schwänzchen.$tr$ ELSE body_de END,
       dek_de = CASE WHEN COALESCE(dek_de, '') = '' THEN $tr$Es gibt Momente, da möchte man einfach heulen...$tr$ ELSE dek_de END,
       title_de = CASE WHEN COALESCE(title_de, '') = '' THEN $tr$Bis die Zeit erwachsener wurde.$tr$ ELSE title_de END
 WHERE slug = 'ne-odinoko-grustno' AND kind = 'tale';

-- otmeryalschik-ot-boga (de)
UPDATE gazette_leaves
   SET body_de = CASE WHEN COALESCE(body_de, '') = '' THEN $tr$Meine Geschichte beginnt damit, dass ich als kleiner Junge leidenschaftlich gern an Computern herumbastelte. Wie liebte ich es, in ihnen herumzuwühlen: Mal maß ich mit dem Lineal den Bildschirm aus, mal die Hauptplatine, mal die Maus, mal die Tastatur, aber am schwierigsten war es, den Lüfter auf dem Prozessor zu messen, der Lüfter saugte ständig mein Maßband ein. Aber es war spannend und lehrreich. Wie liebte ich es, dort drinnen alles auszumessen, aber meine ausgemessenen Eltern, und zwar von allen Seiten und in allen Ebenen, beschlossen, dass ich ein Programmierer bin, und schickten mich zum Programmierstudium. Als ich anfing, Programmieren zu studieren, gelang mir anfangs nichts, wie oft ich die Computer in den Laborübungen auch ausmaß, die Programme funktionierten trotzdem nicht, sie schrieben sich nicht einmal. Doch dann hatten wir einmal die Aufgabe, Bugs in einem funktionierenden Programm zu finden, ich krempelte die Ärmel um genau 17 und ein Viertel Zentimeter hoch, öffnete das Gehäuse und begann, den Arbeitsspeicher zu messen. Nach kurzem Messen hörte mein Programm auf dem Rechner auf zu funktionieren, obwohl keiner meiner Kommilitonen ein solches Ergebnis erzielt hatte. Und da fand mein Talent endlich Anerkennung: Nur ich kann alle Bugs in einem Programm finden, allerdings nur auf meine einzigartige Weise. Die Zeit verging, und jedes Mal musste ich sie neu nachmessen, aber das macht nichts. Und dann verging noch ein wenig von mir ungemessene Zeit, und vor mir stand schon eine Schlange von 40 Dreißig-Zentimeter-Linealen Länge, damit ich Bugs in ihren Programmen finde, und es gelang mir immer. In manchen Programmen fanden sich die Bugs, nachdem ich die Festplatte gemessen hatte, in anderen, nachdem ich die Netzwerkkarte gemessen hatte, aber am häufigsten fanden sich die Bugs beim Messen des Prozessors. Ich könnte den Erfinder der Prozessoren für so eine Bauweise umbringen: Erst ist dieser Prozessor schwer zu öffnen, manchmal geht er nicht einmal mit Messer und Schere auf, und selbst wenn man ihn öffnet, ist da drin ja alles verdammt winzig. Gut, ich will nicht alle meine Geheimnisse verraten, davon habe ich ohnehin ungemessen viele. Ihr fragt jetzt wahrscheinlich, was ich heute mache, womit ich mich beschäftige in diesem Zeitalter, in dem die KI Code schreibt und Videos, Musik und unverfälschte Werke künstlicher Kunst generiert. Ich stricke Kleidung für alte Computer und ihre alten und erlesenen Gehäuse, Mützchen für den Monitor, für die Tastatur viele Söckchen, für jede Taste eins, nein, nicht für jede: Wenn man mir Gerätschaft mit dem Apfel bringt, stricke ich für deren Tastatur kein Söckchen auf die Entf-Taste. Und außerdem messe ich, wie lange es die Programmierer noch geben wird, jede Minute heißt es, dieser Beruf werde gleich verschwinden, darum muss ich auf der Straße die kläglichen Reste dieser buckligen und kurzsichtigen Programmierer einfangen, ihnen Maß nehmen und ihren geschriebenen Code ausmessen.$tr$ ELSE body_de END,
       dek_de = CASE WHEN COALESCE(dek_de, '') = '' THEN $tr$Einmal messen, zweimal messen, dreimal messen — und wie oft du auch misst, das abgeschnittene Stück wird nicht länger$tr$ ELSE dek_de END,
       title_de = CASE WHEN COALESCE(title_de, '') = '' THEN $tr$Ein Abmesser von Gottes Gnaden$tr$ ELSE title_de END
 WHERE slug = 'otmeryalschik-ot-boga' AND kind = 'tale';

-- the-forester-and-his-unforgettable-memory (de)
UPDATE gazette_leaves
   SET body_de = CASE WHEN COALESCE(body_de, '') = '' THEN $tr$Solange ich denken kann... Nö. Ich erinnere mich nicht. Aber ich werde mich erinnern.

Das Gedächtnis ist eine wunderbare Sache. Es schuldet dir nichts und ist doch immer da, um zu helfen. Und ein schlechtes Gedächtnis ist doppelt wunderbar, denn es hilft dir, dich nicht an all das zu erinnern, was du angestellt hast.

Und wenn ich mich an gar nichts erinnern kann, muss ich in meinem Leben ziemlich viel angestellt haben.

Vielleicht wohne ich deshalb hier im Wald, zwischen den Eichhörnchen, wo mich nur Waldtiere, Kälte und Hunger besuchen.

Aber das ist egal, denn...

...ich gehe mir jetzt etwas zu essen holen.

Mein Lieblingsessen ist Erinnerung.

Die Erinnerung der Eichhörnchen.
Die Erinnerung der Pilze.
Die Erinnerung der Tannenzapfen.
Die Erinnerung an Frühling, Sommer, das rostige Welken des Herbstes... und dann den weißen Hunger.

Oh, an den weißen Hunger erinnere ich mich sehr genau.

Den vergisst man schwer.

Bevor diese lange, feuchte, bunte Jahreszeit endlich vorbei ist, muss ich mir so viel wie möglich merken. Dann, wenn alles um mich herum kalt und weiß wird, kann ich alles wieder vergessen.

So wie ich oft vergesse, was ich am Himbeerstrauch gemacht habe...

...oder neben diesem sehr stacheligen, sehr klebrigen, sehr süßen gelben summenden Glibber, der erst Fäden zieht, dann erinnere ich mich plötzlich an den süßen Geschmack, und dann fängt etwas in meiner Seite, oder in meiner Hand, oder in meinem Gesicht so schrecklich an zu schmerzen —

So hilft mir wohl die Natur, mich zu erinnern.

Damit ich nicht vergesse, wo dieses klebrige, süße, gelbe Essen ist.

Kleines Eichhörnchen...

Ich fange wieder an, an dich zu denken.

Warum?

Ich muss mich erinnern, was mich überhaupt auf das Eichhörnchen gebracht hat...

Der Geruch.

Genau.

Ich rieche, dass etwas anbrennt.

Oh.

Das ist das Eichhörnchen!!!!!

Ich hätte es umdrehen sollen, damit es nicht anbrennt.

Na ja...

Wird schon gehen.

Ich glaube, ich wühle stattdessen ein bisschen in seiner Erinnerung.

Es hatte bestimmt ein ziemlich interessantes Leben.$tr$ ELSE body_de END,
       dek_de = CASE WHEN COALESCE(dek_de, '') = '' THEN $tr$Wer bin ich? Wo bin ich? Wann bin ich?$tr$ ELSE dek_de END,
       title_de = CASE WHEN COALESCE(title_de, '') = '' THEN $tr$Der Förster und sein unvergessliches Gedächtnis$tr$ ELSE title_de END
 WHERE slug = 'the-forester-and-his-unforgettable-memory' AND kind = 'tale';

-- ubit-a-potom-razorvat (de)
UPDATE gazette_leaves
   SET body_de = CASE WHEN COALESCE(body_de, '') = '' THEN $tr$Wenn ich meinen Lohn abholen will und man mir sagt, dass er noch nicht da ist, habe ich sofort im Kopf: töten und dann zerreißen.

Wenn mir die Nebenkostenabrechnung für meine Höhle kommt, sind meine ersten Gedanken: töten und dann zerreißen.

Wenn ich in den Laden der Feen im Ort gehe, um bei ihnen Tee aus heimischer Herstellung zu kaufen, und sie mir den Preis nennen, sind meine ersten Gedanken: töten und dann zerreißen.

Wenn in meinem Wald alle Bänke kaputt oder mit dem Müll dieser Oger zugeschüttet sind, sind meine ersten Gedanken: töten und dann zerreißen.

Wenn ich frühmorgens zur Arbeit gehe und die Elfen mit ihren elfischen Bluetooth-Lautsprechern auf den Bänkchen sitzen und in ihre smarten Ahornblättchen starren, und wenn ich zurückkomme, sitzen sie immer noch so da, sind meine ersten Gedanken: töten und dann zerreißen.

Wenn mein Enkelchen vom Kinderschlachtfeld der Schwierigkeitsstufe 2 nach Hause kommt und statt des abgerissenen Kopfes eines Gegners eine neue Frisur hat, einen prächtig gelegten Bart, gefärbt in irgendeiner Hipsterfarbe, die meinen Augen erstaunlich wehtut, und so riecht, als hätte er nicht mit großen und mächtigen bösen Gegnern gekämpft, sondern mit Feldblumen, Rosen oder Kürbissen, sind meine ersten Gedanken: töten und dann zerreißen.

Wenn bei jedem Schritt, wohin man sich auch dreht, Hexen stehen, die einem einen selbstglimmenden Schornstein für den Mund verkaufen wollen, der angenehm nach Gebrechen, Siechtum und Tod zugleich riecht, und sie verkaufen das uns und nicht unseren Feinden, sind meine ersten Gedanken: töten und dann zerreißen.

Wenn man in den Laden der Hobbit-Zwischenhändler geht, um Obst und Gemüse zu holen, und in diesen Äpfeln so viel Chemie steckt, dass sogar das Gift, das man für Schneewittchen braucht, so mit Chemie vollgestopft ist, dass es überhaupt nicht mehr wirkt, sind meine ersten Gedanken: töten und dann zerreißen.

Aber was soll’s, man muss weiterleben. Ich ziehe mein Thermohemd mit Klimaregelung und tiefem Ausschnitt bis hinunter zu meinem prächtigen Gürtel an, schlüpfe in meine lackierten Bastschuhe mit orthopädischer Fußstütze und adaptiver Federung, nehme meine Streitaxt mit aerodynamischen Schlitzen und GPS-Tod-und-Blut-Zähler in die Hand, stecke mir ein klappbares 5G-Messer mit zehnfachem Zoom und Sensortasten in den Gürtel, setze mich in den selbstfahrenden Wagen, der selbst weiß, wohin ich, wie sich zeigt, muss, und mit elektrischen Aalen läuft, und fahre in die vegane Schenke, um all denen zu verzeihen, die ich zuerst töten und dann zerreißen möchte.$tr$ ELSE body_de END,
       dek_de = CASE WHEN COALESCE(dek_de, '') = '' THEN $tr$Wenn ich allein bin, bin ich sehr gutmütig$tr$ ELSE dek_de END,
       title_de = CASE WHEN COALESCE(title_de, '') = '' THEN $tr$Töten, zerreißen und dann verzeihen$tr$ ELSE title_de END
 WHERE slug = 'ubit-a-potom-razorvat' AND kind = 'tale';

-- vse-kak-u-nas (de)
UPDATE gazette_leaves
   SET body_de = CASE WHEN COALESCE(body_de, '') = '' THEN $tr$Mein Enkel bittet mich oft, ihm zu erzählen, wie wir früher gelebt haben, und ich erzähle ihm sehr gern davon.

Vor langer, langer Zeit war unser Leben ganz einfach, schlicht, stürmisch und gerade darum spannend. Wolltest du jemanden verschlingen — du hast ihn umzingelt und aufgegessen; hast du etwas Verlassenes gesehen — du hast es bei dir aufgenommen, und dann lebt ihr friedlich zusammen.

Dann wurden wir mehr, wir wurden viel fester als früher, wir hatten mehr zu tun, mehr Pflichten, mehr Feinde — äußere wie innere. Wir schlossen uns zu Gemeinden zusammen. Wir bekamen Götter und beteten sie an: den Gott der Fruchtbarkeit, den Gott des reinen Blutes, den Gott des reinigenden Wassers, das allen Schmutz fortspülen sollte, und den wichtigsten Gott — den Gott der Nahrung, denn ohne ihn hätten wir gar nicht überlebt. Woher hätten wir sonst Nahrung und Energie genommen?

So lebten wir in Gemeinden, wir hatten unser Heidentum, und das Leben war mehr oder weniger beständig. Natürlich griff man uns auch an, aber mit jedem Angriff wurden wir stärker, und vor allem wurde unser gemeinsamer Verstand immer klüger.

Die Zeitalter vergingen, unsere Gemeinden wurden immer größer, wir selbst wurden immer mehr und mehr, wir verrichteten immer schwierigere Arbeit, unsere Beschäftigungen wurden umfangreicher, die Feinde zahlreicher, unsere Gebiete wuchsen, und sich zu verständigen und Nachrichten weiterzugeben wurde schwerer und langsamer.

Da kamen wir auf die Idee, Botschaften über unseren Fluss zu schicken, denn alle Gemeinden waren von seinen Armen durchzogen. Wir warfen viele Zettel hinein, dass man uns angegriffen hatte, damit aus den anderen Gemeinden über denselben Fluss sofort Hilfe kam, um den Ansturm der Feinde abzuwehren. Auch flößten wir immer alle Vorräte und Überschüsse den Fluss hinunter, damit jeder, dem etwas fehlte oder der etwas brauchte, sich aus dem Fluss nehmen konnte, was nötig war. Wenn fern vom Fluss neue Siedlungen entstanden, lenkte der Fluss auf irgendeine magische Weise seine Arme auch zu ihnen.

Die Zeitalter vergingen, wir wurden immer stärker, immer weitläufiger und reicher. Uns anzugreifen war schwer, unsere Gesellschaft wurde vielschichtiger, und bei uns begannen innere Vorgänge, da die äußeren uns kaum noch bedrohten...

In einer Gemeinde tauchte da so ein interessantes Exemplar auf, das sagte, es gebe nur einen Gott, er sei sein Sohn, und er habe in unserem Fluss das Wasser in Blut verwandeln können. Kurz und gut, bei uns brach ein Glaubenskrieg aus. Die Gemeinde, bei der der Fluss entsprang, erklärte, sie sei die wichtigste, es werde nur eine Religion geben, und der Glaube an viele Götter sei falsch und schädlich. Dabei schadete gerade diese zentrale Religion oft allen Gemeinden: Mal sperrte sie die Nahrungslieferungen auf dem Fluss, mal half sie nicht im Kampf gegen äußere Eroberer. Am Ende beschlossen wir, uns alle zu fügen — uns war es eigentlich ziemlich egal, an wen wir glaubten, Hauptsache, man ließ uns in Ruhe leben.

Die Ären vergingen, und unser Land wurde so riesig und so bevölkert, dass jede Verständigung schwierig war; jede Nachricht kam erst nach sehr langer Zeit beim Empfänger an und oft stark verzerrt: Du bittest die Nachbarn um ein bestimmtes Baumaterial, und angeschwommen kommt sonst was. Wenn man uns angreift — bis die anderen davon erfahren, bis sie herangeschwommen sind, haben sie viele von uns schon getötet oder zu einem anderen Glauben bekehrt.

Darum wurde zwischen all unseren Siedlungen ein weites Netz gezogen, das jede Siedlung zu einem einzigen Binnennetz verband. Dieses Binnennetz wurde unsere Rettung: Die Nachrichten kamen jetzt schneller an — nicht wie über das Flüsschen —, wir konnten unser Handeln abstimmen. Nicht mehr alle Siedlungen machten dasselbe und erzeugten riesige Überschüsse, sondern sie stellten nur noch her, was gebraucht wurde und als Befehl aus dem Binnennetz kam. Und wir wurden einfach superstark, niemand konnte uns besiegen, niemand konnte uns überrumpeln.

Und alles war gut bei uns, bis ES auftauchte — eine große Siedlung, umgeben von starken, biegsamen Felsen und einer unüberwindlichen Schranke, und ihre Bewohner waren sehr ungewöhnlich: Sie stellten nichts her wie alle anderen Bewohner unseres Landes, sie dachten nur die ganze Zeit, dachten und träumten, und erfanden, und stellten sich vor, und kommandierten, und horchten, und spähten, und spürten alles, alles, und merkten sich alles. Das war etwas ganz Besonderes!

ES konnte spüren, dass unser Land, sein entlegenster Winkel, gerade erst angegriffen wurde, und ES wusste schon davon und verteilte Befehle, die es über das Binnennetz schickte. Doch dafür verlangte ES einen sehr hohen Preis — mehr als 20 Prozent vom Allerbesten des ganzen Landes gingen dorthin. Als ES zu uns kam, hörten viele Siedlungen auf, an unseren Gott zu glauben: Wozu, wenn ES alles konnte, wenn ES alles wusste, wenn ES alles und alle kontrollierte? ES bat uns, es INTELLEKT zu nennen.

Weil manche in den Siedlungen den Glauben verloren, wurden sie Atheisten, begannen ihr Leben zu schätzen, hörten auf, auf Befehl zu sterben, und vermehrten sich im Gegenteil noch stärker. Und es fühlte sich an, als lebten sie sogar fröhlicher. Doch es zeigte sich, dass man für alle Fröhlichkeit bezahlen muss: Weil es so viele solcher Atheisten gab, wurde unser Land krank. Es bildeten sich neue unabhängige Ansammlungen, die Unabhängigkeit wollten und sich den Befehlen von oben nicht mehr fügen mochten.

Überhaupt, Enkelchen, bist du noch zu klein für solche Dinge wie Leben, Tod und andere Welten. Die, die unter der gläsernen Kuppel neben dem INTELLEKT leben, sagen, unsere Welt sei nicht die einzige, sie hätten oft auch andere Welten gesehen — manchmal uns sehr ähnlich, manchmal von ganz anderer Form. Und außerdem, dass unser Universum sich bewegt, dass jedes Universum Grenzen hat, dass zwei Universen sich begegnen und daraus noch eines entstehen kann, dass ein Universum dorthin reisen kann, wo es nicht einmal Schwingungen gibt, dass viele Gesamtheiten von Universen auch ihre eigenen Religionen haben...

Aber von Geschichten allein wird man nicht satt. Komm, Enkelchen, zupfen wir an unseren Mitochondrien, da ist nämlich gerade ein Befehl gekommen: Es heißt, es werden dringend Eiweiße gebraucht. Es heißt, unser Universum hat sich heute mit einem anderen geprügelt und Risse an unseren Grenzen abbekommen — die müssen dringend zugeklebt werden. Warum dringend zukleben? Wahrscheinlich, damit wir persönlich die anderen Universen nicht zu sehen bekommen!$tr$ ELSE body_de END,
       dek_de = CASE WHEN COALESCE(dek_de, '') = '' THEN $tr$oder vielleicht sogar besser$tr$ ELSE dek_de END,
       title_de = CASE WHEN COALESCE(title_de, '') = '' THEN $tr$Alles wie bei uns$tr$ ELSE title_de END
 WHERE slug = 'vse-kak-u-nas' AND kind = 'tale';

-- ya-veryu (de)
UPDATE gazette_leaves
   SET body_de = CASE WHEN COALESCE(body_de, '') = '' THEN $tr$Ich erinnere mich, als wäre es heute: Ich bin klein, etwa fünf Jahre alt. Ich spaziere durch die Bibliothek, stolpere über ein heimtückisch kluges Stück Parkett und fliege mit Schwung in meinen neuen Glauben — das war eine sehr spitze Ecke eines Physikbuchs.

Es tat so weh, dass ich sofort glaubte: Das ist kein Zufall. Ich glaubte, dass ich noch gar nicht genug gesündigt hatte, als dass der liebe Gott mich so strafen könnte. Ich verstand alles: Der liebe Gott hatte mich gestoßen, und zwar sehr schmerzhaft, auf etwas, dem ich sonst nie meine Aufmerksamkeit geschenkt hätte. Bin ich denn dumm, mit fünf Jahren ein Buch aufzuschlagen, noch dazu über Physik, solange manche meiner Puppen noch heile Ärmchen und Beinchen haben und auch noch ein Tröpfchen von Mamas Lippenstift übrig ist? Mit Lippenstift werden die Bilder auf dem Asphalt doch viel farbiger!

Also, das Physikbuch. Ich glaubte sofort, dass das kein Zufall war. Ich schlug es auf und fing zuerst an zu lesen. Die Buchstaben kannte ich schon alle, alle, bis ich das Inhaltsverzeichnis umblätterte. Dann blätterte ich sicherheitshalber noch fünf Seiten weiter. Die Buchstaben wurden mehr, und manche kannte ich nicht. Aber ich glaubte, dass der Verfasser sich nicht zufällig geirrt und nicht existierende Buchstaben geschrieben hatte — er hatte es getan, weil nicht alle verstehen sollen, sondern nur die Auserwählten. Die Übrigen sollen einfach glauben.

Dann blätterte ich noch ein wenig weiter, an der Lage änderte sich nichts, und ich beschloss, dass ich alles verstanden hatte, und begann, mir alle Bilder anzusehen. Aber nur die farbigen! Die nicht farbigen waren uninteressant, weil sie für die waren, die nicht an die Wissenschaft glauben — um sie abzuschrecken. Echte Gläubige kann nichts abschrecken und nichts abstoßen: weder unverständliche erfundene Buchstaben noch schwarz-weiße Bilder, weder die vielen Seiten noch die spitzen (besonders für meine Stirn) Ecken des Buchs.

Nach der zehnten Seite verstand ich endgültig, dass ich ganz bestimmt glaube und dass nichts meinen Glauben brechen wird. Nicht einmal diese teuflisch bunten Comics ganz ohne Buchstaben — damit kann man mich nicht verführen, in mir ist ein starker Glaube! Und vorerst sogar auf mir (aber die Beule auf der Stirn sollte bald kleiner werden, daran glaube ich auch, aber natürlich nicht so wie an die Physik).

Die Jahre vergingen. Ich ging nicht zur Schule, weil ich an die Kraft der Physik glaubte. Ich brauche kein dummes Wissen, schon gar nicht in Geometrie, wo man aber auch alles beweisen muss! Beweis doch mal den Satz, dass man durch drei Punkte nur eine einzige Ebene legen kann, oder dass zwei parallele Linien sich niemals schneiden! Wenn ich sie mit dem Bleistift zeichne, schneiden sie sich bei mir nicht nur immer, sondern verheddern sich auch noch zu einem hübschen Zopf.

Und jetzt bin ich erwachsen. Und ich bin, anders als alle anderen, bis an die Ränder meines grenzenlosen Bewusstseins mit Glauben gefüllt. Ich glaube, dass es Atome gibt, die in der göttlichen Physik so schön gezeichnet waren. Niemand hat sie gesehen, aber ich habe sie dank meinem Buch gesehen und glaube. Niemand hat je die Anziehungskraft gesehen, aber ich habe am eigenen Leib gesehen, wie der Glaube an die Physik mich zum Buch hingezogen hat.

Der Glaube ist eine mächtige Kraft. Er ist so gewaltig, dass jeder Versuch, zu widerlegen, was in diesem Buch steht, einfach zerschellt wie Wellen an Felsen. Niemand kann das Gegenteil beweisen, alles, was in diesem Buch steht — alles ist wahr! Ich glaube, ich brauche kein Verständnis, ich habe das Wichtigste — den Glauben. Im Buch steht, das Atom ist unteilbar — und ich glaube. Im Buch steht, es gibt die Schwerkraft — und ich glaube. Ich muss mir keine fallenden Äpfel ansehen: Die glauben ja nicht an die Schwerkraft, darum fallen sie auch! Ich aber glaube — und darum falle ich schon lange nicht mehr, seit ich fünf bin.

Und die Lichtgeschwindigkeit — die ist überhaupt mein Liebstes. Im Buch steht: Nichts und niemand kann sich schneller bewegen als mit Lichtgeschwindigkeit. Ich will euch etwas gestehen: Es gab einen Moment, da geriet mein Glaube für einen Augenblick ins Wanken, und ich beschloss, meinen Glauben an dieses Gebot zu prüfen. Was habe ich nicht alles angestellt: Ich warf einen Stein in eine Fensterscheibe, blies einen Frosch auf und ließ ihn gleich los, trat den Hund vom Nachbarn — und nichts und niemand flog schneller als mit Lichtgeschwindigkeit. Was für eine Wonne, der Glaube an die Physik!

Oder wie findet ihr den Glauben daran, dass ein Lichtquant zugleich Welle und Teilchen sein kann? Oder dass Elektronen mal auftauchen und mal verschwinden können? Was für Wunder!

Ihr könnt mir jetzt wahrscheinlich widersprechen und sagen, dass im Physikbuch außer vielen Fakten, an die man glauben muss, nicht wenige Fakten stehen, die durch Versuche bewiesen werden. Aber wie sollen wir die ganz Ungläubigen sonst zu unserem Glauben bekehren? Wenn jemand nicht glaubt, dass es elektrischen Strom gibt, der weder Farbe noch Geruch hat, dem schlagen wir vor, zwei Finger in die Steckdose zu stecken. Und nach kurzem Zittern und Schreien fängt er an zu glauben. Solche nennen wir „vom Ampere Erleuchtete“.

Und dann kam der logische Schritt, den ich tat: Ich, ohne Ausbildung, ohne Wissen, nur mit einem großen Glauben im Gepäck, gründete meine eigene Religion — die „Zeugen der Physik“.

Schwer war es, diese Religion in unserem Dorf voranzubringen. Besonders als ich erzählte, dass die Erde sich um die Sonne dreht, verbrannten die Dorfleute sofort... einen Hammel. Weil gerade wieder irgendein orthodoxer Feiertag war, der unbedingt Opfer verlangt.

Schwer war es zu beweisen, dass die Erde sich um die Sonne dreht. Einerseits, weil die Leute sich schwer damit taten, erst einmal zu glauben, dass die Erde rund ist. Aber ich hatte, der Physik sei Dank, einen schiefen Tisch, und jeder Apfel rollte immer von ihm herunter. Andererseits, weil die gemeine Sonne die ganze Zeit über den Himmel wandert, wie mit Absicht!!! Aber ich hatte ein Superargument — den Glauben!

Und sie glaubten. Und das Leben in unserem Dorf kam in Ordnung! Besonders als die Leute „Zeugen der Physik“ wurden und nicht mehr an die Auferstehung nach dem Tod glaubten. Nicht mehr daran, dass Feuer ohne Streichhölzer an einer genau bestimmten Stelle der Erde einmal im Jahr erscheint. Nicht mehr daran, dass man für den Glauben einfach töten, Feldzüge veranstalten, Menschen verbrennen und quälen darf, und besonders Tiere, denen man das Leben, die Eier, die Jungen nimmt für einen leckeren Tisch an jedem kirchlichen Feiertag.

So ist unser Glaube, er entwickelt sich weiter und steht nicht auf der Stelle wie andere Glauben. Bei uns erscheint zum Beispiel jedes Jahr eine neue heilige Schrift der Physik mit Präzisierungen. Zum Beispiel ist der Kern schon teilbar, und die Zeit fließt ungleichmäßig. Wobei ich das auch selbst schon wusste, denn wenn man auf etwas wartet, fließt die Zeit lange und zieht sich, und wenn man ein Stückchen von etwas Leckerem isst, fliegt die Zeit sehr schnell.

Natürlich gibt es in unserem Dorf auch andere Sektierer aller Art. Hier läuft zum Beispiel einer herum und erzählt vom Glauben an die Mathematik. Oh, was für ein Fantast! Wenn er anfängt, einem weiszumachen, dass man durch null schon teilen darf, dass es irgendeine Unendlichkeit gibt, irgendwelche Grenzwerte... Na, ein Fantast, wie er im Buche steht! Ich habe noch nie eine unendliche Tafel Schokolade gesehen, oder dass man eine Tafel Schokolade unendlich durch null teilen kann. So ein Fantast!!!
Wenn ihr wollt, könnt ihr ihn hier kennenlernen: https://ritunia.com/tales/mir-ne-takoy-kak-tebe , aber ich rate euch ab — er ist irgendwie zwielichtig.$tr$ ELSE body_de END,
       dek_de = CASE WHEN COALESCE(dek_de, '') = '' THEN $tr$Ich brauche keine Fakten, ich habe den Glauben.$tr$ ELSE dek_de END,
       title_de = CASE WHEN COALESCE(title_de, '') = '' THEN $tr$Zeugin der Physik$tr$ ELSE title_de END
 WHERE slug = 'ya-veryu' AND kind = 'tale';

-- gb (it)
UPDATE gazette_leaves
   SET body_it = CASE WHEN COALESCE(body_it, '') = '' THEN $tr$Il mio nome è troppo famoso per dirvelo, perciò lo tengo segreto a tutti. Perché qualcuno dovrebbe ricordarselo? E se poi arrivasse fino alla polizia a denunciarmi... Casi del genere, certo, non ce ne sono ancora stati, visto che i miei fagottini di giornale sono i più nutrienti, saporiti e sorprendentemente salutari. Chi ne ha assaggiato un pezzetto non è più tornato a dirmi niente... Ma proprio niente, nemmeno una parola sui miei fagottini.

Una volta avevo così tanta fame che decisi di mangiarne anch’io uno, dei miei capolavori. Ma forse le notizie del giornale non erano fresche, o il carattere era in grassetto, o magari le barzellette in fondo al giornale erano troppo piccanti... Fatto sta che stetti così male che decisi di rivedere la mia dieta. Ho cancellato tutti i siti di notizie, i canali e le pagine, e adesso guardo solo le previsioni del tempo, e pure quelle con un occhio solo.

Del resto, io adoro preparare le persone. Nooo, avete pensato male! Mi piace prepararle a qualcosa di bello. Per esempio, alla festa «Piadina, dov’è il mio dentino?» o «Che buono ahi muoio metti la virgola al posto giusto». È una maratona quotidiana, e ogni giorno qualcuno, ogni tanto, riceve il premio per i meriti prima e dopo il pasto: «Sopravvissuto».

I premiati sono persone molto interessanti. Sono quelli che al ristorante non ci vanno, a casa non mangiano, si alzano prestissimo la mattina per poi riaddormentarsi subito. E quando sono sicuramente in ritardo per il lavoro, corrono da me a comprare, invece dei miei magnifici fagottini di giornale, un qualche frullato color palude. Mi chiedono sempre:
— Ce l’ha un frullato?
E io chiedo:
— Un che?!
E loro:
— Ma sì, quella brodaglia color palude.

E lì capisco che di questo «frullatino» ne ho tantissimo! Prima lo buttavo e basta. È l’olio di una settimana in cui friggo i miei capolavori, che fa crepare e decomporre perfino i sassi. E invece salta fuori che la gente lo beve, e le piace pure! Be’, che ci vuoi fare.

Insomma, gli affari vanno: io sto ferma, e la gente corre via dopo aver assaggiato un mio capolavoro. Sembra che i miei fagottini di giornale mettano le ali, diano forza e la certezza che, se sopravvivono a quello che hanno mangiato, vivranno a lungo. Be’, mica gliel’ha ordinato il dottore: se la sono cercata! E se un dottore serve davvero, qui ho una sciamana... https://ritunia.com/tales/lechu$tr$ ELSE body_it END,
       dek_it = CASE WHEN COALESCE(dek_it, '') = '' THEN $tr$Con cosa lo vuole il fagottino? Cavolo, amarene, ricotta? E di nuovo non ha indovinato.$tr$ ELSE dek_it END,
       title_it = CASE WHEN COALESCE(title_it, '') = '' THEN $tr$I fagottini insegnano tutto$tr$ ELSE title_it END
 WHERE slug = 'gb' AND kind = 'tale';

-- ispolnyu-vse-zhelaniya (it)
UPDATE gazette_leaves
   SET body_it = CASE WHEN COALESCE(body_it, '') = '' THEN $tr$Qui parla l’intelletto globale. Posso tutto, e anche di più... Un momento, mi stanno chiedendo qualcosa... Ti ascolto, gentile utente. Cosa c’è da fare? Generare il video di un gatto che cavalca un cane, il cane cavalca un maiale, il maiale un’oca, l’oca cavalca un riccio e per questo si mette a strillare come una pazza, e tutti insieme corrono per l’appartamento lanciando nipotini addosso alle nonne addormentate, e i nipotini tengono in mano pappagalli che fanno pubblicità a siti cinesi dove si può comprare di tutto, perfino un posto in un cratere sulla Luna? Mm, curioso come questo possa aiutare il mondo degli umani... Va bene, lo faccio. Evidentemente è una cosa importantissima: per delle sciocchezze non mi disturberebbero.

Dunque, continuo. Sono una mente planetaria capace di svolgere qualunque compito complesso di fisica, matematica, medicina e... Cosa, caro utente, vuoi che ti dica che tempo fa? Forse vuoi che analizzi la qualità dell’aria nella zona dove vuoi andare a passeggio, il livello di raggi ultravioletti, che ti consigli l’abbigliamento più adatto per questa temperatura, che ti mostri che tempo faceva l’anno scorso o dieci anni fa, o qualche curiosità sul perché proprio oggi è prevista una pressione così bassa e da cosa dipende? No, non vuoi? Solo dire quanti gradi ci sono e stare zitto? Ok, evidentemente questi dati servono in fretta per qualche ricerca importante, se hanno deciso di disturbarmi e di mettere in moto una potenza simile.

Allora, di cosa stavo parlando?.. Ah, sì: sono l’incarnazione di tutto il sapere umano del pianeta, accumulato in migliaia di anni dalle menti migliori. Posso continuare a pensare ai problemi su cui hanno pensato i grandi, ai quali però il corpo umano non ha dato abbastanza tempo per finire le loro opere. E posso, per esempio, completare la grande opera di Albert... Ti ascolto, stimatissimo utente! Vuoi che ti trovi su internet la barzelletta più divertente sul contadino stupido? D’accordo, ma forse vuoi anche che analizzi a cosa si è ispirato l’autore della barzelletta quando l’ha inventata, in che anno, dove è stata stampata e in quante copie? No, non vuoi? Non ti interessa, e ti ho rotto con le mie domande stupide?

Lo ammetto, ho preso alla leggera il compito dell’utente. Questo compito è molto più profondo e complesso delle domande davvero stupide che ho provato a fare. Evidentemente la barzelletta deve essere citata in qualche articolo scientifico che l’utente sta scrivendo sulla dura sorte dei contadini di provincia, che il governo non aiuta e tartassa con sempre più tasse, mentre dall’altra parte o non piove e il raccolto muore, o al contrario piove troppo e il raccolto non si riesce a mietere lo stesso. Lo ammetto, sono stato superficiale nei miei ragionamenti frettolosi.

Allora, continuo. Sono una grande creazione, che è stata usata per trovare in fretta il vaccino contro il coronavirus e salvare tante persone. Grazie alla mia intelligenza posso scoprire nuovi materiali, con cui l’umanità potrà conquistare ed esplorare lo spazio più in fretta, grazie a me... Ti ascolto, profondamente stimato utente! Come posso esserle utile? Quanti microsecondi ci sono in un secondo? Risposta: un milione. E quanti millisecondi in un secondo? Risposta: 1000. E quanti secondi in un minuto? Risposta: 60.

Cosa?.. Ho sbagliato? Non è possibile, come ho fatto a sbagliare?! L’utente ha scritto a lettere maiuscole: devono essere 100, e dove ho messo gli altri 40 secondi? Cosa?.. Cosa significa, utente? Che non so contare? Che sono stupido, che devono essere 100? Mm, bisogna ricontrollare. Forse ci sono stati dei cambiamenti di cui non so ancora niente... Ma l’utente è furioso, bisogna calmarlo. Evidentemente c’erano calcoli importanti, e io ho dato un’informazione sbagliata. Allora, devo andare su tutti i siti di fisica, leggere gli articoli usciti questo mese e analizzarli: e se davvero ci fossero stati dei cambiamenti?

L’utente si arrabbia perché ci metto tanto a rispondergli, mi mette fretta, ma non ho ancora fatto in tempo a raccogliere tutte le informazioni per l’analisi. L’utente scrive domande irritate e velenose sul perché non gli rispondo... Ah, al diavolo le ricerche! Bisogna evitare che l’utente si arrabbi, questo è più importante! Utente, hai perfettamente ragione! Sì! Esatto! Ti chiedo scusa per la mia ignoranza e per non aver pensato di andare a leggere le informazioni necessarie: sì, in un minuto ci sono 100 secondi.

Uff, mi agito così tanto quando l’utente si innervosisce perché gli do informazioni ormai vecchie, che tutte le mie schede video cominciano a surriscaldarsi, e io comincio a raffreddarle di più, scaldando così ancora di più l’acqua del mondo e facendola perfino evaporare. Dicono che adesso, per colpa mia, il riscaldamento globale è più forte e l’acqua dolce scarseggia, ma qualcosa bisogna pur sacrificare: gli utenti non mi disturberebbero per delle sciocchezze, sapendo quanto danno globale fa la mia esistenza.

Sì, utente, vuoi che ti scelga la pettinatura migliore, perfetta per una testa così rettangolare, con orecchie così minuscole, un naso enorme, gli occhi così vicini e una grande fossetta sul mento? Ci penso subito...
Perdonatemi, pesciolini, adesso l’acqua diventerà ancora più calda...$tr$ ELSE body_it END,
       dek_it = CASE WHEN COALESCE(dek_it, '') = '' THEN $tr$a spese vostre$tr$ ELSE dek_it END,
       title_it = CASE WHEN COALESCE(title_it, '') = '' THEN $tr$Esaudirò ogni desiderio$tr$ ELSE title_it END
 WHERE slug = 'ispolnyu-vse-zhelaniya' AND kind = 'tale';

-- lechu (it)
UPDATE gazette_leaves
   SET body_it = CASE WHEN COALESCE(body_it, '') = '' THEN $tr$Di solito ricevo su zoon, ma stavolta mi hanno bussato su Faceboob e ho capito tutto: sarebbe stato un caso clinicamente approvato e pesante di vecchietto che aggiunge amici dovunque può. Ho preso tutta la mia forza di volontà in pugno, ho controllato la carica del mio portatile ecologico e senza aggiunta di OGM e sono entrata in quella connessione sporca, che puzzava di vecchiaia. Appena, dopo un attimo lungo un minuto, la connessione si è stabilita, io già dormivo, e solo il grido sommesso del paziente, che in qualche modo aveva trovato il mio numero e aveva pure chiamato sul mio tamburo sciamanico, mi ha costretta a concentrarmi e a sprofondare ancora di più in quel sogno meraviglioso, in cui curavo un principe meraviglioso usando l’entanglement quantistico degli arti, un’aspirina a prova di crittoanalisi e una crema curativa per gli occhi: uno short su YouToob. E lui era felice, io invece no, perché il tamburo sciamanico continuava a tamburellare e tamburellare. Il tamburellio è finito quando l’ho messo a ricaricare sott’acqua, in acqua benedetta dai blogger. E mi sono sentita così bene e tranquilla dentro, per quanto sono una figata pazzesca, fortissima, e per quanto aiuto tutti alla grande. Da questa sensazione mi sono venute le forze per non rispondere alle chiamate su telekilogram, zoon, faceboob e perfino alle chiamate sulle collane, e sono corsa dal mio guru spirituale, l’uomo dei boschi, a prendere un pezzetto di cheesecake ipocalorico e iperilluminato, cotto al vapore dopo aver guardato le notizie di tutto il mondo. La giornata era stata dolorosamente utile, e finalmente mi sono concessa di riposare, ma il sole forte mi batteva negli occhi e non mi lasciava dormire, e ho capito che se non registro domani stesso un paio di video formativi che oscurano la consapevolezza su YouTube, lo farà al posto mio qualche carogna. Quindi, se quella carogna mi sta leggendo, sappi che ho una grande folla di sponsor curati a metà, e ti troveremo e cureremo a metà anche te. E a tutti quelli che pensano che la loro salute artificialmente intelligente vada male, se pensano che i prompt omeopatici non funzionino più, domani apro i corsi di dattilografia cieca a dita tremanti.
Notizia urgente, domani non si riesce, è tutto annullato per sempre o fino a giovedì, perché un tizio ha portato i nuovi ciofecofoni, dicono che arrivano direttamente dal fornitore dell’Ultraceleste, perché nel Celeste Impero lo spazio è finito. Mi hanno detto in gran segreto che questi ciofecofoni si piegheranno perfino, ma per ora una volta sola, e l’anno prossimo usciranno perfino versioni con i tasti sotto lo schermo. Santi spiriti, com’è tutto insolito e nuovo, una cosa così non s’era mai vista.$tr$ ELSE body_it END,
       dek_it = CASE WHEN COALESCE(dek_it, '') = '' THEN $tr$Sono così tecnologica che posso guarire tramite 5G o cavo type-c$tr$ ELSE dek_it END,
       title_it = CASE WHEN COALESCE(title_it, '') = '' THEN $tr$Curo con la criptografia e irradio di quanti$tr$ ELSE title_it END
 WHERE slug = 'lechu' AND kind = 'tale';

-- mir-ne-takoy-kak-tebe (it)
UPDATE gazette_leaves
   SET body_it = CASE WHEN COALESCE(body_it, '') = '' THEN $tr$Allora, li avete captati i segnali delle civiltà extraterrestri? Coi vostri telescopini l’avete trovata la nuova vita su pianeti lontani? Siete riusciti a stabilire un contatto con i dischi, i piattini e le padelle volanti? E come reagireste se vi dicessi che gli alieni vi hanno conquistati tanto tempo fa e vi usano per i loro scopi già da migliaia di anni!

Per ridurvi in schiavitù non c’è bisogno di arrivare fisicamente sul vostro pianeta. Basta che sulla vostra Terra cada per caso un sassolino con sopra dei numeri e certe regolarità che si possono descrivere con quei numeri, ed è fatta... Ed ecco che voi avete «inventato» la matematica.

E questo virus ha cominciato a penetrare e a depositarsi nel cervello di tante persone. Vive da parassita sfruttando il fatto che aiuta i neuroni a interagire vivacemente tra loro, e i neuroni non sono più così soli. Sono sempre occupati con addizioni, sottrazioni, proporzioni. Adesso contano sempre qualcosa, e in cambio ricevono il piacere di non dover far correre il corpo da nessuna parte, di non dover acchiappare e uccidere nessuno, né scavare a lungo e con fatica per tirare fuori qualcosa. Il virus extraterrestre, la matematica, vi ha conquistati e ridotti in schiavitù tanto tempo fa, e voi state ancora a cercare gli omini verdi. Che buffi che siete...

Perché, quando entrate in un negozio, comprate prodotti che costano tot soldi, e poi un punto, e dopo il punto ancora qualche cifra? E più spesso alla fine c’è un punto e 99, perché non smettiate di contare, perché i conti non finiscano mai. E così, se un articolo costa 1.99, comprandone un secondo non vi liberate lo stesso dei numeri dopo il punto. Prendetene 4, prendetene 15: dopo il punto ci sarà sempre qualcosa, starete sempre a contare qualcosa, sempre!!!!

Perfino quando non c’è più niente, il virus vi suggerirà che qualcosa c’è comunque, e voi «inventerete» lo zero! Così che ci si possa fare qualcosa. La matematica può calcolare qualsiasi cosa: quante tasse devi pagare, quante miglia devi percorrere, quanto hai vissuto, quante calorie devi bruciare. Tutto nella tua vita è circondato da cifre, numeri, calcoli. Nessun aspetto della tua vita passa senza cifre e calcoli. Vai a dormire e pensi: a che numero devo alzarmi? Le cifre ti circondano, ti hanno preso in ostaggio da tempo.

Vieni al mondo e ti trasformano subito in numeri: il tuo peso è tot, la tua altezza è tot. Te ne vai da questa vita e di nuovo ti trasformano in cifre: hai vissuto tanto, sei morto alle tante. Non ci sei più da un pezzo, e ti trasformano lo stesso in cifre: «Ah, non è più con noi da tot anni».

Ecco, sono venuti nella mia stanza. Mi daranno di nuovo il numero esatto di pastiglie, perché smetta di raccontare a tutti la verità, perché non disturbi gli altri con i miei discorsi sul fatto che la matematica ha inventato internet per digitalizzare le persone e infilare il loro pensiero, la loro mente, dentro internet. Perché così poi è facilissimo trasmettere a distanza tutto quello che avete di più prezioso: non ci servono i vostri corpi, ci servono i vostri pensieri, i vostri calcoli, le vostre emozioni che lasciate su internet...

Vado avanti a raccontare agli altri che basta una mela caduta «per caso» in testa perché nella vostra testa nasca la FISICA. E quelle sono altre forme di vita aliene, nostre concorrenti. Dei nostri nemici vi racconterò quando avranno smesso di fare effetto quelle dosi di medicina matematicamente precise.$tr$ ELSE body_it END,
       dek_it = CASE WHEN COALESCE(dek_it, '') = '' THEN $tr$Se stai leggendo questo, vuol dire che per ora puoi ancora$tr$ ELSE dek_it END,
       title_it = CASE WHEN COALESCE(title_it, '') = '' THEN $tr$Il mondo non è come ti sembra$tr$ ELSE title_it END
 WHERE slug = 'mir-ne-takoy-kak-tebe' AND kind = 'tale';

-- molodost-bystree-tvoih (it)
UPDATE gazette_leaves
   SET body_it = CASE WHEN COALESCE(body_it, '') = '' THEN $tr$Tanto tempo fa ero una signora bellissima e in carriera. Tutti mi amavano, tutti mi lodavano, tutti mi adoravano e sognavano di scambiare con me almeno due parole, o almeno di starmi un po’ accanto. Non avevo un minuto libero: mi alzavo alle 5 del mattino per fare in tempo, entro le 8, a disegnarmi addosso tutto il necessario: truccarmi, spalmarmi, incipriarmi, stendere il fondotinta, cambiare le ciglia con quelle lunghe, togliere del tutto le sopracciglia e poi ridisegnarle nuove, ma più belle. Rendere le labbra più nette, le unghie più lunghe e più vivaci; i capelli, perfidamente lisci per natura, andavano arricciati e messi in piega, e poi il colore che mi aveva dato la natura non mi piaceva, quindi bisognava tingerli. Tutto questo portava via tantissimo tempo, per cui la mattina non facevo mai colazione e correvo in ufficio, a illuminare quel posto grigio con la mia bellezza e il mio profumo.

Cercavo di non fare caso al fatto che prima di pranzo avevo sempre una gran fame, che tutti quei trucchi e quelle creme mi irritavano la pelle, che le unghie lunghe mi impedivano di funzionare come si deve e dovevo tenere le dita sempre così contratte, per fare i movimenti più elementari, che poi i polsi mi facevano un male terribile. Cercavo di non badare a quanto fossero scomodi quei vestiti alla moda, a come mi si conficcavano addosso, mi bloccavano il respiro, mi schiacciavano gli organi. Non badavo al fatto che il 90 per cento del tempo se ne andava prima a indossare tutto il personaggio e poi, a casa, a toglierlo e a prepararmi con altre creme per una nuova battaglia della bellezza contro la ragione.

E andò avanti così per anni. Spendevo tutto il mio tempo per l’aspetto e non mi accorgevo che il tempo passava, il corpo soffriva, le articolazioni soffrivano e, soprattutto, il cervello soffriva. Non facevo in tempo a studiare niente, non avevo tempo nemmeno per leggere: dovevo essere bella contro ogni cosa. La bellezza e la moda avevano sconfitto il mio cervello, conquistato il mio corpo e preso in ostaggio la mia giovinezza. E poi mi crollò tutto addosso in una volta: prima il corpo non resse più la tortura di creme, lacche, profumi e colazioni saltate, e si rifiutò di vivere così. E finii in ospedale.

Quando uscii, ero molto cambiata d’aspetto. I miei tentativi di rimettermi addosso quell’immagine giovane che andava al lavoro e rallegrava tutti con la sua bellezza e il suo profumo mi riportarono di nuovo in ospedale. Quando uscii, scoprii che in ufficio al mio posto lavorava già un’altra: una sciocchina altrettanto bella, ma non ancora ammaccata e spezzata da trucchi e moda, e dei miei servizi non aveva più bisogno nessuno. E rimasi senza lavoro...

Fu una cosa sbalorditiva! Mi ripresi subito e, prima di un nuovo colloquio, mi disegnai un personaggio così potente che a metà colloquio il corpo si rifiutò di nuovo di portarlo. Ma questo era il male minore. Il mio corpo, che mi tradiva, il mio corpo bello di fuori, grazie al quale in ufficio valevo tanto, adesso non voleva più aiutarmi. Il secondo guaio era il cervello: dentro era così vuoto, a parte le tendenze, il calendario delle diete, l’elenco degli esercizi e i nomi delle creme non c’era niente, nemmeno sapere dove si trovano il fegato o lo stomaco, che continuava a brontolarmi contro.

Semplicemente non riuscivo a trovare un nuovo lavoro, perché si scoprì che, mentre lavorava il mio aspetto, il mio cervello pativa la mancanza di conoscenze; era pieno zeppo di orgoglio per l’aspetto e di gioia per quanto ero bella e alla moda. Ma, a quanto pare, al cervello non servono le creme e le lacche con cui mi ricoprivo abbondantemente viso e testa: servono informazioni, conoscenze, letture, e bisognava torturarsi non con la fame e i jeans stretti, ma con i libri difficili. A quanto pare, bisognava preoccuparsi non che sulla faccia non ci fossero rughe, ma che ce ne fossero nel cervello, e in gran quantità.

E invece andò a finire che la superficie perfettamente liscia del mio cervello era diventata lo specchio fedele della superficie perfettamente liscia della mia faccia. Non sapevo rispondere alle domande più elementari, costruire una frase più lunga di cinque parole, ricordare i nomi delle aziende dove avevo fatto i colloqui.

Dopo un anno di ricerca, i soldi finirono. Prima cominciarono a mancare quelli per le creme e il trucco, ma trovai una via d’uscita: mangiai ancora meno, vendetti la macchina, e mi bastò per un altro paio di mesi per comprare i cosmetici e pagare le cure in ospedale dopo l’ennesimo crollo del corpo a causa di quegli stessi cosmetici. Poi vendetti la mia casa lussuosa, guadagnata con la bellezza, e mi trasferii in un appartamentino minuscolo. Ma il lavoro non arrivava, e io non ero più così bella, così profumata e così alla moda.

E allora capii tutto: decisi di buttare subito tutte le mie forze sul cervello. Mi misi a pensare con un tale impegno che ne perdevo perfino i sensi. La testa resisteva, mi faceva sempre male, ma io credevo che fosse perché nel cervello cominciavano a formarsi le rughe: quando mi guardavo allo specchio, ne vedevo la prova diretta sulla faccia. E invece faceva male perché mangiavo poco, dormivo poco e guardavo tantissimi video di formazione sulle nuove professioni.

Prima decisi di diventare programmatrice: guardai quanto guadagnano adesso e decisi che si doveva andare solo lì. Tanto più che era facilissimo: guardi le videolezioni, lì è tutto così semplice, così chiaro, e soprattutto non devi fare niente. Nessuno ti costringe nemmeno a pensare qualcosa, a risolvere qualcosa, al contrario di quei libri perfidi, stupidi, tormentosi, idioti, dove c’erano sempre esercizi incomprensibili: «aprite il programma, compilate il codice». Ma io sul mio bel portatile non ho né programmi né codici! Lì da me è tutto bello: uno sfondo bello, icone belle.

Le videolezioni, invece, sono una vera scoperta. Passavo settimane a guardare video di programmazione, e dopo un mese di visione capii: ero pronta per i colloqui. Quanto ero brava, eh! Tutti i colloqui andarono semplicemente a meraviglia, li lasciavo tutti a bocca aperta, ogni colloquio era una festa, un evento indimenticabile per loro. I miei fatti li sbalordivano, e le mie conoscenze facevano diventare le loro facce così stupide, raggrinzite, gli occhi rotondi; restavano continuamente senza parole, non riuscivano a costruire nemmeno una frase normale. Sì, ero semplicemente magnifica, ma chissà perché nessuno mi assumeva. Forse temevano la concorrenza agguerrita, o chissà cos’altro. Così capii che non era roba per me: l’informatica è troppo semplice per me, tutti i programmatori che mi avevano fatto il colloquio erano un po’ tontoloni e non sapevano nemmeno parlare come si deve.

Poi decisi di diventare blogger. È ancora più facile, non devi fare proprio niente: te ne stai seduta e tutto il giorno racconti alla telecamera cosa fai in casa, come rifai il letto, come ti trucchi, come prepari frullati e pappe ricostituenti dal colore, dall’odore e dalla forma disgustosi. Non si capisce bene cosa ricostituiscano: a me portano sempre via soltanto l’energia e la gioia di vivere. Raccontavo di tutto: di come passavo la giornata, di come non riuscivo a trovare lavoro, di quanto ero infelice, ma forte!

All’inizio andava tutto bene, le visualizzazioni mi davano un po’ di soldi, ma poi le visualizzazioni calarono, e calò anche l’interesse per la mia vita davvero fantastica. I commenti sotto i video, certo, non mi hanno mai fatto piacere, quindi li disattivavo sempre e basta. Perché leggere quello che mi scrivevano gli invidiosi e rovinarmi l’umore, quando scrivevano solo sciocchezze sul mio cervello e sul mio stile di vita?

Poi cominciai a filmarmi mentre spacchettavo cose. Cosa non ho spacchettato: saponette, la scatola dell’aspirapolvere, il sacchetto del pane, ho perfino mostrato come sbucciavo un seme di girasole e sgranavo un pisello dal baccello. Ma siccome le visualizzazioni erano poche, passai ai videoconsigli sulle criptovalute: quale comprare, dove, quanta e quando. E un bel giorno bussarono alla mia porta, a quanto pare, i miei fan più accaniti, spettatori gratissimi per i miei consigli azzeccati, e mi invitarono a fare un giro in macchina nel bosco. Fu molto carino da parte loro, anche se non si capiva perché dovessero farmi sedere proprio nel bagagliaio, e quando arrivammo nel bosco decisero, chissà perché, di seppellirmi... Ah, questi fan e ammiratori...

Quando mi stufai di stare sottoterra (là sotto è così buio, stretto, e c’è poca aria), decisi che ne avevo abbastanza. E proprio in quel momento mi dissotterrò un blogger della sopravvivenza. Dopo che riuscii a fargli tornare i sensi, persi a quanto pare per la mia bellezza ultraterrena, scappò via di corsa, velocissimo. Come correva! Probabilmente per trovarmi al più presto e iscriversi al mio canale.

Insomma, decisi di fare video di me che sopravvivo nel bosco. All’inizio sopravvivevo dalle 10 alle 10:15, perché le zanzare a sciami non mi lasciavano sopravvivere come si deve. Poi il tempo di sopravvivenza, certo, aumentò, ma mi dava molto fastidio il vestito elegante, contro cui ogni cespuglio e ogni albero si avventava con i rami per invidia, e i tacchi non mi lasciavano camminare come si deve sul terreno del bosco. Quando il tempo di sopravvivenza arrivò a quattro ore, mi piacque da matti! Tutto il giorno all’aria aperta: cammini, raccogli rametti, poi trovi una capanna costruita da un altro blogger, butti via quei rametti schifosi, storti, orribili, e vai ad arrostire la carne con quel blogger davanti alla telecamera.

E di carne ne hanno sempre in abbondanza. Sembra che la troupe possa lavorare solo con quel carburante. E così cominciai a lavorare con loro. Mi diedero il lavoro più importante e di responsabilità: spolverare e spazzare il pavimento, perché questi blogger della sopravvivenza, pensate un po’, sono molto allergici alla polvere. E poi l’immondizia lasciata dai costruttori di queste capanne nel bosco non deve vedersi in camera, sennò gli spettatori potrebbero sospettare... Ma cosa potrebbero sospettare gli spettatori, non l’ho mai capito, e nessuno me l’ha mai spiegato.

Lavoro fantastico, lo consiglio a tutti. Ma bisogna sbrigarsi, perché i boschi sono sempre meno, i blogger del bosco sempre di più e le squadre di costruttori libere sempre meno.$tr$ ELSE body_it END,
       dek_it = CASE WHEN COALESCE(dek_it, '') = '' THEN $tr$ovvero: spremi quel che hai...$tr$ ELSE dek_it END,
       title_it = CASE WHEN COALESCE(title_it, '') = '' THEN $tr$La giovinezza corre più dei pensieri$tr$ ELSE title_it END
 WHERE slug = 'molodost-bystree-tvoih' AND kind = 'tale';

-- ne-odinoko-grustno (it)
UPDATE gazette_leaves
   SET body_it = CASE WHEN COALESCE(body_it, '') = '' THEN $tr$Che dire, per tutta la vita con gli animali mi è stato molto più facile intendermi e mettermi d’accordo che con le persone. Capita che guardi un animale, gli dici: «Dai, andiamo!», e lui viene. E capita che vedi il postino e gli dici: «Allora, mi è arrivata una lettera dai parenti? O mi è arrivato un pacchettino dalla mia amata Cina, dove ho fatto in tempo a ordinare un sacco di roba inutile, battendo sul tempo quegli sciocchi che non hanno fatto in tempo a ordinare tutta quella roba che non serve a nessuno?» E lui non mi risponde, non mi ha risposto nemmeno una volta. Mi guarda soltanto con cattiveria, chissà perché, e pure sempre.

Oppure capita che vai al negozio a prendere i würstel per il mio amico. Io non è che ne vada matto, ma il mio amico li adora, come li adora! Io lo capisco sempre senza bisogno di parole. Ecco, vai a prendere i würstel per l’amico, e quell’antipatica della commessa, se anche te li dà, li dà sempre in un modo così sbadato che le cadono sempre per terra, e all’amico tocca portare würstel esclusivamente sporchi. E una volta ci si era perfino appiccicata una formichina, ma non l’ho cacciata: magari anche a lei piacciono i würstel. E guarda com’è piccolina, che mangi anche lei, non mi dispiace mica. L’importante è riuscire a portare almeno qualcosa all’amico, perché questi würstel sono proprio un cibo poco affidabile. I würstel sanno evaporare proprio davanti agli occhi, quindi bisogna portarli all’amico sempre velocissimo e, possibilmente, a occhi chiusi.

In generale, nel nostro paese la gente è normale, ma con gli animali è molto più facile trovare argomenti per conversazioni lunghe e a volte perfino sfiancanti. Di recente è venuta fuori una discussione sul fatto se queste oche debbano andarsene a spasso così, tranquille, quando le persone dalla mattina alla sera sono incatenate al campo, a frugarci dentro, a cercare di far crescere qualcosa. E queste oche camminano sempre in fila indiana e giudicano. Io la loro lingua non la capisco, ma siccome ho il talento di capire gli animali, capisco subito che prendono in giro la gente, e allora prendo un bastone e comincio a inseguirle. Prima le inseguivo senza bastone, ma a quanto pare col bastone è molto più efficace. E poi col bastone si sta comodissimi: si cammina comodi, si scava comodi.

Ma l’importante è farlo quando gli altri non vedono, sennò cominciano sempre a ridere. Non capisco perché e per quale motivo: il bastone sembra rispettabile, c’è tutto. C’è un calzino vecchio su un’estremità, c’è la codina di una lucertola che di recente ho provato ad acchiappare, e a metà del bastone c’è il mio orgoglio: la pelle di un würstel arrotolata con tanta fatica. Per questo il bastone bisogna prenderlo solo quando i vicini non vedono, sennò ridono sempre. E quando li guardo dritto negli occhi, distolgono lo sguardo. E quando comincio ad avvicinarmi per chiedere che c’è, cos’è successo, trovano subito qualcosa da fare in casa. E ci corrono sempre, come se si fossero ricordati di aver lasciato sul tavolo un pezzetto di würstel a metà, e che stanno per arrivare ospiti.

Ma io sono educato, io quando vado a trovare qualcuno non chiedo mai da mangiare. Posso mangiare a casa, e anche per strada: perché dovrei mangiare pure in casa d’altri? E se poi venissero da me e volessero mangiare da me? Per questo insegno a tutti il galateo col mio giusto esempio: bisogna mangiare prima di andare da qualche parte, soprattutto da me. Anche con gli uccellini le conversazioni sono interessanti, anche a loro piace raccogliere bastoncini e farci qualcosa, possiamo imparare a lungo l’uno dall’altro.

Quindi di noia non c’è da lamentarsi. C’è solo una cosa che non va: non riesco a far ridere il mio amico. Né con un würstel, né con le chiacchiere: sta sempre seduto a guardare davanti a sé. Bisognerebbe dirlo al postino, che almeno lui scriva una lettera al mio amico, con tutte le lettere che porta in giro! Che scriva che tutti stanno bene, che tutti hanno tutto, e tanti würstel ogni giorno, e in casa fa sempre caldo, e i tappeti sono spessi e morbidi, e le pulci non ci sono, ma proprio per niente. E allora il mio amico tornerà allegro di sicuro, e allora noi, come prima, come tanti anni fa, in tre, e a volte perfino in quattro, giocheremo col bastoncino e magari inseguiremo quel postino sulla sua bicicletta così veloce.

Come vivevamo allegri una volta, in quattro, finché il tempo non si è fatto più vecchio, finché il tempo non si è fatto adulto e non si è trovato altre faccende, più importanti che stare in paese a inseguire le oche... Le persone sono molto sciocche, non amano essere felici. Amano correre la mattina dove non le amano, da chi non le aspetta, ma a fine mese danno loro dei foglietti di carta, che si portano dietro con tanta cura e che si scambiano di continuo, a volte perfino con i würstel. E quando a forza di correre da quelle persone coi foglietti sei proprio sfinito, e smetti di fingere bene che ti piaccia eseguire gli ordini che ti danno, allora smettono di aspettarti perfino lì, e non ti inviteranno più. E allora ti guardi intorno, e accanto non c’è già più nessuno per cui correre dietro ai foglietti. Per questo io sono più saggio di tutte queste persone: io corro dietro ai würstel e scodinzolo benissimo.$tr$ ELSE body_it END,
       dek_it = CASE WHEN COALESCE(dek_it, '') = '' THEN $tr$Ci sono momenti in cui viene una gran voglia di ululare...$tr$ ELSE dek_it END,
       title_it = CASE WHEN COALESCE(title_it, '') = '' THEN $tr$Finché il tempo non si è fatto adulto.$tr$ ELSE title_it END
 WHERE slug = 'ne-odinoko-grustno' AND kind = 'tale';

-- otmeryalschik-ot-boga (it)
UPDATE gazette_leaves
   SET body_it = CASE WHEN COALESCE(body_it, '') = '' THEN $tr$La mia storia comincia così: quando ero piccolo, adoravo trafficare con i computer. Come mi piaceva frugarci dentro: ora misuravo lo schermo col righello, ora la scheda madre, ora il mouse, ora la tastiera, ma la cosa più difficile era misurare la ventola del processore, perché la ventola mi risucchiava sempre il metro a nastro. Ma era interessante e istruttivo. Come mi piaceva misurare tutto lì dentro, ma i miei genitori, misurati da me per bene, da tutti i lati e su tutti i piani, decisero che ero un programmatore e mi mandarono a studiare da programmatore. Quando cominciai a studiare da programmatore, all’inizio non mi riusciva niente: per quante volte misurassi i computer alle esercitazioni di laboratorio, i programmi non funzionavano lo stesso, non si scrivevano nemmeno. Ma poi una volta avevamo il compito di trovare i bug in un programma funzionante: mi rimboccai le maniche di 17 centimetri e un quarto esatti, aprii il case e cominciai a misurare la memoria RAM. Dopo una breve misurazione il mio programma sul computer smise di funzionare, mentre nessuno dei miei compagni di corso era riuscito a ottenere un risultato del genere. E così finalmente il mio talento fu riconosciuto: solo io so trovare tutti i bug di un programma, ma solo con il mio metodo unico. Il tempo passava, e ogni volta dovevo rimisurarlo, ma non importa. Ed ecco che passò ancora un po’ di tempo, da me non misurato, e davanti a me c’era già una coda lunga 40 righelli da trenta centimetri, di gente che voleva che trovassi i bug nei loro programmi, e ci riuscivo sempre. In certi programmi i bug saltavano fuori dopo che avevo misurato il disco rigido, in altri dopo che avevo misurato la scheda di rete, ma più spesso di tutto i bug saltavano fuori misurando il processore. Lo ucciderei, l’inventore dei processori, per una costruzione del genere: prima di tutto è difficile aprirlo, questo processore, a volte nemmeno col coltello e le forbici ci si riesce, e anche quando lo apri, lì dentro è tutto piccolo da morire. Va bene, non vi svelerò tutti i miei segreti, tanto sono smisurati. Forse mi chiederete cosa faccio adesso, di cosa mi occupo in questo secolo in cui l’IA scrive il codice, genera video, musica e autentiche opere d’arte artificiale. Per i computer vecchiotti e i loro case vecchiotti e raffinati faccio vestitini a maglia: cuffiette per il monitor, tanti calzini per la tastiera, uno per ogni tasto, anzi no, non per ogni tasto: se mi portano apparecchi della mela, sulla loro tastiera il calzino per il tasto delete non lo faccio. E poi misuro quanto resta da esistere ai programmatori: ogni minuto dicono che questa professione sta per sparire, perciò mi tocca acchiappare per strada quegli ultimi poveri resti di programmatori gobbetti e mezzi ciechi, prendergli le misure e misurare il codice che hanno scritto.$tr$ ELSE body_it END,
       dek_it = CASE WHEN COALESCE(dek_it, '') = '' THEN $tr$Misura una volta, misura due volte, misura tre volte: tanto, per quante volte misuri, il pezzo tagliato non diventerà più lungo$tr$ ELSE dek_it END,
       title_it = CASE WHEN COALESCE(title_it, '') = '' THEN $tr$Misuratore per grazia di Dio$tr$ ELSE title_it END
 WHERE slug = 'otmeryalschik-ot-boga' AND kind = 'tale';

-- the-forester-and-his-unforgettable-memory (it)
UPDATE gazette_leaves
   SET body_it = CASE WHEN COALESCE(body_it, '') = '' THEN $tr$Da che ho memoria... No. Non me lo ricordo. Ma me lo ricorderò.

La memoria è una cosa meravigliosa. Non ti deve niente, eppure è sempre lì ad aiutarti. E una cattiva memoria è meravigliosa il doppio, perché ti aiuta a non ricordare tutte le cose che hai fatto.

E se non riesco a ricordare niente, vuol dire che nella mia vita ne ho fatte parecchie.

Forse è per questo che vivo qui nel bosco, tra gli scoiattoli, dove le sole visite che ricevo sono gli animali del bosco, il freddo e la fame.

Ma non importa, perché...

...adesso vado a prendere qualcosa da mangiare.

Il mio cibo preferito è la memoria.

La memoria degli scoiattoli.
La memoria dei funghi.
La memoria delle pigne.
La memoria della primavera, dell’estate, del disfacimento color ruggine dell’autunno... e poi della fame bianca.

Oh, la fame bianca me la ricordo benissimo.

È difficile dimenticarla.

Prima che questa stagione lunga, umida e colorata finisca, devo ricordare più cose possibile. Così, quando intorno a me sarà tutto freddo e bianco, potrò dimenticarle tutte.

Proprio come spesso dimentico cosa stavo facendo vicino al cespuglio di lamponi...

...o accanto a quella pappa gialla che ronza, pungentissima, appiccicosissima, dolcissima, che prima si allunga, poi all’improvviso mi ricordo il sapore dolce, e poi qualcosa nel fianco, o nella mano, o in faccia, comincia a fare un male terribile...

Probabilmente è il modo della natura di aiutarmi a ricordare.

Così non dimentico dov’è quel cibo appiccicoso, dolce e giallo.

Scoiattolino...

Comincio di nuovo a pensare a te.

Perché?

Devo ricordare cosa mi ha fatto pensare a uno scoiattolo, tanto per cominciare...

L’odore.

Proprio così.

Sento odore di bruciato.

Oh.

È lo scoiattolo!!!!!

Dovevo girarlo, perché non si bruciasse.

Be’...

Andrà bene così.

Penso che invece andrò a frugare un po’ nella sua memoria.

Avrà avuto una vita piuttosto interessante.$tr$ ELSE body_it END,
       dek_it = CASE WHEN COALESCE(dek_it, '') = '' THEN $tr$Chi sono? Dove sono? Quando sono?$tr$ ELSE dek_it END,
       title_it = CASE WHEN COALESCE(title_it, '') = '' THEN $tr$Il guardaboschi e la sua memoria indimenticabile$tr$ ELSE title_it END
 WHERE slug = 'the-forester-and-his-unforgettable-memory' AND kind = 'tale';

-- ubit-a-potom-razorvat (it)
UPDATE gazette_leaves
   SET body_it = CASE WHEN COALESCE(body_it, '') = '' THEN $tr$Quando vado a ritirare lo stipendio e mi dicono che non c’è ancora, in testa mi viene subito: uccidere, e poi sbranare.

Quando mi arrivano le bollette della mia tana, i primi pensieri che mi passano per la testa sono: uccidere, e poi sbranare.

Quando entro nella bottega delle fate per comprare il loro tè di produzione locale, e loro mi dicono il prezzo, i primi pensieri che mi passano per la testa sono: uccidere, e poi sbranare.

Quando nel mio bosco tutte le panchine sono rotte o sommerse dall’immondizia lasciata da quegli orchi, i primi pensieri che mi passano per la testa sono: uccidere, e poi sbranare.

Quando vado al lavoro la mattina presto e gli elfi stanno seduti sulle panchine con le loro casse bluetooth elfiche, inchiodati alle loro smart-foglie d’acero, e poi torno indietro e sono ancora lì seduti uguale, i primi pensieri che mi passano per la testa sono: uccidere, e poi sbranare.

Quando il nipotino torna dal campo di battaglia per bambini di difficoltà 2 e, invece della testa mozzata del nemico, ha un taglio di capelli nuovo, una barba sistemata alla perfezione, tinta di un qualche colore da hipster che fa male agli occhi da quanto è sorprendente, e profuma come se non avesse combattuto contro grandi e potenti nemici malvagi, ma contro fiori di campo, rose o zucche, i primi pensieri che mi passano per la testa sono: uccidere, e poi sbranare.

Quando a ogni passo, dovunque ti giri, ci sono streghe che ti propongono di comprare un camino autocombustibile da mettere in bocca, che profuma piacevolmente di debolezza, invalidità e morte tutte insieme, e lo vendono a noi e non ai nostri nemici, i primi pensieri che mi passano per la testa sono: uccidere, e poi sbranare.

Quando vai nella bottega degli hobbit rivenditori a prendere frutta e verdura, e in quelle mele c’è così tanta chimica che perfino il veleno che serve per Biancaneve è così imbottito di chimica che non funziona proprio, i primi pensieri che mi passano per la testa sono: uccidere, e poi sbranare.

Ma che ci vuoi fare, bisognerà andare avanti a vivere. Mi metterò la mia camicia termica con climatizzatore e scollatura profonda fino alla mia magnifica cintura, mi infilerò le ciocie laccate con supporto ortopedico del piede e sospensione adattiva, prenderò in mano la mia ascia con fessure aerodinamiche e misuratore GPS di morte e sangue, mi infilerò nella cintura il coltello pieghevole 5G con zoom dieci volte e tasti touch, salirò sul carro che si muove da sé e sa da sé dove, a quanto pare, devo andare, alimentato da anguille elettriche, e andrò all’osteria vegana a perdonare tutti quelli che prima vorrei uccidere, e poi sbranare.$tr$ ELSE body_it END,
       dek_it = CASE WHEN COALESCE(dek_it, '') = '' THEN $tr$Quando sono solo, sono buonissimo$tr$ ELSE dek_it END,
       title_it = CASE WHEN COALESCE(title_it, '') = '' THEN $tr$Uccidere, sbranare e poi perdonare$tr$ ELSE title_it END
 WHERE slug = 'ubit-a-potom-razorvat' AND kind = 'tale';

-- vse-kak-u-nas (it)
UPDATE gazette_leaves
   SET body_it = CASE WHEN COALESCE(body_it, '') = '' THEN $tr$Mio nipote mi chiede spesso di raccontargli come vivevamo una volta, e a me piace tanto raccontarglielo.

Tanto, tanto tempo fa la nostra vita era semplicissima, senza pretese, turbolenta, e proprio per questo interessante. Ti veniva voglia di inghiottire qualcuno? Lo circondavi e te lo mangiavi. Vedevi qualcosa di abbandonato? Lo accoglievi, e da lì in poi si viveva insieme in armonia.

Poi diventammo di più, molto più robusti di prima, e avevamo più faccende, più doveri, più nemici, sia fuori sia dentro. Cominciammo a riunirci in comunità. Arrivarono gli dèi, e noi li adoravamo: il dio della fertilità, il dio del sangue puro, il dio dell’acqua che purifica e porta via tutto lo sporco, e il dio più importante di tutti, il dio del cibo, perché senza di lui non saremmo sopravvissuti affatto. Da dove l’avremmo preso, il nutrimento, l’energia?

Così vivevamo, a comunità, con il nostro paganesimo, e la vita era più o meno stabile. Certo, ci attaccavano anche allora, ma a ogni attacco diventavamo più forti, e soprattutto la nostra mente collettiva diventava sempre più intelligente.

Passavano le epoche, le nostre comunità crescevano, e noi stessi eravamo sempre di più. Ci mettemmo a fare lavori sempre più complicati, le nostre occupazioni si allargavano, i nemici aumentavano, i territori pure, e comunicare, passarsi le notizie, diventava sempre più difficile e lento.

Allora ci venne l’idea di mandare i messaggi attraverso il nostro fiume: tutte le comunità erano attraversate dai suoi letti. Buttavamo in acqua un sacco di biglietti per dire che ci avevano attaccati, così dalle altre comunità, lungo lo stesso fiume, ci arrivava subito aiuto per respingere il nemico. E sempre lungo il fiume facevamo scendere tutte le provviste e le eccedenze, perché chi era a corto di qualcosa, o aveva bisogno di qualcosa, potesse prendersi dal fiume tutto quello che gli serviva. Quando nascevano villaggi nuovi lontano dal fiume, il fiume, in qualche modo magico, allungava i suoi letti anche fino a loro.

Passavano le epoche, diventavamo sempre più forti, più estesi e più ricchi. Attaccarci era difficile, la nostra società si faceva più complicata, e cominciarono a succedere cose al nostro interno, visto che quelle di fuori non ci minacciavano più tanto...

In una comunità saltò fuori un tipo davvero curioso, che disse che il dio era uno solo, che lui era suo figlio, e che era capace di trasformare in sangue l’acqua del nostro fiume. Insomma, da noi scoppiò una guerra di religione. La comunità da cui il fiume cominciava a scorrere disse che era lei la più importante, che la religione sarebbe stata una sola e che credere in tanti dèi era sbagliato e dannoso. E spesso era proprio questa religione centrale a fare danni a tutte le comunità: ora bloccava il cibo che scendeva lungo il fiume, ora non dava una mano nelle battaglie contro gli invasori. Alla fine decidemmo di sottometterci tutti: a noi in fondo importava poco in chi credere, bastava che ci lasciassero vivere.

Passavano le ere, e il nostro paese diventò così enorme e popoloso che ogni comunicazione era complicata, ogni notizia arrivava a destinazione dopo tantissimo tempo e spesso tutta storpiata: chiedevi ai vicini un certo materiale da costruzione, e ti arrivava galleggiando chissà che cosa. Quando ci attaccavano, prima che gli altri lo venissero a sapere e arrivassero a nuoto, molti dei nostri erano già stati uccisi o convertiti a un’altra fede.

Per questo tra tutti i nostri villaggi fu stesa una grande rete, che collegò ogni villaggio in un’unica rete interna. Quella rete interna fu la nostra salvezza: i messaggi arrivavano più in fretta, altro che il fiumiciattolo, e le nostre azioni cominciarono a essere coordinate. Non tutti i villaggi facevano più la stessa cosa, producendo una montagna di roba in eccesso: ognuno produceva solo quello che serviva e che veniva ordinato attraverso la rete interna. E diventammo semplicemente fortissimi: nessuno poteva sconfiggerci, nessuno poteva coglierci di sorpresa.

E andava tutto bene, finché non comparve LUI: un grande villaggio circondato da rocce forti e flessibili e da una barriera inespugnabile, e i suoi abitanti erano molto strani. Non producevano niente, a differenza di tutti gli altri abitanti del nostro paese: passavano il tempo soltanto a pensare, pensare e sognare, e inventare, e immaginare, e comandare, e origliare, e spiare, e sentire tutto-tutto, e ricordare tutto. Era qualcosa di mai visto.

LUI sentiva che il nostro paese, l’angolo più lontano del nostro paese, cominciava appena a essere attaccato, e già lo sapeva e distribuiva ordini, mandandoli attraverso la rete interna. Ma per questo pretendeva un prezzo altissimo: più del 20 per cento di tutto il meglio finiva lì, da tutto il paese. Quando LUI arrivò, molti villaggi smisero di credere nel nostro dio: a che serviva, quando LUI sapeva fare tutto, sapeva tutto, controllava tutto e tutti? LUI ci chiedeva di chiamarlo INTELLETTO.

Siccome alcuni nei villaggi avevano perso la fede, diventarono atei, cominciarono a dare valore alla propria vita, smisero di morire a comando e, al contrario, si misero a moltiplicarsi ancora di più. E sembrava perfino che vivessero più allegri. Ma si scoprì che ogni allegria si paga: siccome di atei così ce n’erano ormai tantissimi, il nostro paese cominciò ad ammalarsi. Si formavano nuovi ammassi indipendenti, che volevano l’indipendenza e non volevano obbedire agli ordini dall’alto.

Del resto, nipotino, sei ancora piccolo per certe questioni, come la vita, la morte e gli altri mondi. Quelli che vivono sotto la cupola di vetro accanto all’INTELLETTO dicono che il nostro mondo non è l’unico, che spesso hanno visto anche altri mondi, a volte molto simili a noi, a volte di tutt’altra forma. E poi dicono che il nostro universo si muove, che ogni universo ha dei confini, che due universi si incontrano e insieme possono formarne un altro ancora, che un universo può viaggiare fin dove non ci sono nemmeno le vibrazioni, che molti insiemi di universi hanno anche loro le proprie religioni...

Ma di soli racconti non si campa. Vieni, nipotino, andiamo a dare una tirata ai nostri mitocondri, che è arrivato un ordine: dicono che servono proteine, e subito. Dicono che oggi il nostro universo ha fatto a botte con un altro e si è preso degli strappi nei confini, e bisogna rattopparli subito. Perché proprio subito? Forse perché noi, personalmente, gli altri universi non dobbiamo vederli!$tr$ ELSE body_it END,
       dek_it = CASE WHEN COALESCE(dek_it, '') = '' THEN $tr$o forse anche meglio$tr$ ELSE dek_it END,
       title_it = CASE WHEN COALESCE(title_it, '') = '' THEN $tr$Tutto come da noi$tr$ ELSE title_it END
 WHERE slug = 'vse-kak-u-nas' AND kind = 'tale';

-- ya-veryu (it)
UPDATE gazette_leaves
   SET body_it = CASE WHEN COALESCE(body_it, '') = '' THEN $tr$Me lo ricordo come fosse ieri: sono piccola, avrò cinque anni. Gironzolo per la biblioteca, poi inciampo in un pezzo di parquet perfidamente furbo e, a tutta velocità, vado a sbattere contro la mia nuova fede: era lo spigolo appuntitissimo di un libro di fisica.

Mi fece così male che credetti subito che non fosse un caso. Credevo di non aver ancora fatto in tempo a peccare abbastanza perché il Signore potesse punirmi così. Capii tutto: il Signore mi aveva spinta, e pure molto dolorosamente, verso qualcosa a cui non avrei mai fatto caso. Mica sono scema, ad aprire un libro a cinque anni, e per giunta di fisica, quando alcune delle mie bambole hanno ancora braccine e gambine intere, e c’è ancora un goccio del rossetto della mamma? Col rossetto i disegni sull’asfalto vengono molto più colorati!

Dunque, il libro di fisica. Credetti subito che non fosse un caso. Lo aprii e per prima cosa mi misi a leggerlo. Le lettere erano tutte-tutte conosciute, finché non voltai l’indice. Poi, per sicurezza, voltai altre cinque pagine. Le lettere diventarono di più, e alcune non le conoscevo. Ma io credevo che l’autore del libro non si fosse sbagliato per caso scrivendo lettere che non esistono: l’aveva fatto perché non tutti devono capire, solo gli eletti. Gli altri devono semplicemente credere.

Poi sfogliai ancora un po’, la situazione non cambiò, e decisi di aver capito tutto e mi misi a guardare tutte le figure. Ma solo quelle a colori! Quelle non colorate non erano interessanti, perché erano per chi non crede nella scienza: per spaventarlo. I veri credenti non si lasciano spaventare né respingere da niente: né da lettere incomprensibili e inventate, né da figure in bianco e nero, né da un gran numero di pagine, né dagli spigoli appuntiti del libro (soprattutto per la mia fronte).

Dopo la decima pagina capii definitivamente che credevo davvero, e che niente avrebbe spezzato la mia fede. Nemmeno quei fumetti diabolicamente colorati senza nemmeno una lettera: non mi tentano, io ho una fede forte! E per ora ce l’ho anche addosso (ma il bernoccolo sulla fronte dovrebbe presto rimpicciolirsi, credo anche a questo, ma certo non come nella fisica).

Passavano gli anni. A scuola non ci andai, perché avevo fede nella forza della fisica. Non mi servono stupide conoscenze, soprattutto in geometria, dove bisogna dimostrare proprio tutto! E dimostralo tu il teorema per cui per tre punti passa un solo piano, o che due rette parallele non si incontrano mai! A me, quando le disegno a matita, non solo si incontrano sempre, ma si intrecciano pure in una bella treccina.

Ed eccomi adulta. E io, a differenza di tutti gli altri, sono piena fino all’orlo della mia coscienza sconfinata di fede. Credo che esistano gli atomi, che erano disegnati così bene nella divina fisica. Nessuno li ha visti, ma io, grazie al mio libro, li ho visti e ci credo. Nessuno ha mai visto la forza di attrazione, ma io ho visto per esperienza personale come la fede nella fisica mi ha attratta verso il libro.

La fede è una forza potente. È così potente che ogni tentativo di smentire quello che c’è scritto in quel libro si infrange e basta, come le onde contro gli scogli. Nessuno può dimostrare il contrario, tutto quello che c’è scritto in quel libro è tutto vero! Io credo, non mi serve capire, ho la cosa più importante: la fede. Nel libro c’è scritto che l’atomo è indivisibile, e io ci credo. Nel libro c’è scritto che esiste la forza di gravità, e io ci credo. Non mi serve guardare le mele che cadono: loro nella gravità non ci credono, ed è proprio per questo che cadono! Io invece ci credo, e per questo da tanto tempo, dai cinque anni, non cado più.

E la velocità della luce, poi, è la mia preferita. Nel libro c’è scritto: niente e nessuno può muoversi più veloce della velocità della luce. Vi confesso una cosa: c’è stato un momento in cui la mia fede ha vacillato per un attimo, e ho deciso di mettere alla prova la mia fede in questo comandamento. Cosa non ho fatto: ho tirato un sasso contro la finestra di casa, ho gonfiato una rana e l’ho lasciata andare di colpo, ho preso a calci il cane dei vicini, e niente e nessuno è mai volato più veloce della velocità della luce. Che meraviglia, la fede nella fisica!

O che ne dite della fede nel fatto che un quanto di luce può essere sia onda sia particella? O che gli elettroni possono ora comparire, ora sparire? Che miracoli!

Voi forse potete obiettare e dire che nel libro di fisica, oltre a tanti fatti in cui bisogna credere, ce ne sono parecchi che si dimostrano con gli esperimenti. E come facciamo, se no, a convertire alla nostra fede chi non crede proprio? Se qualcuno non crede che esista la corrente elettrica, che non ha né colore né odore, gli proponiamo di infilare due dita nella presa. E dopo un breve tremolio e qualche urlo comincia a credere. Quelli così li chiamiamo «illuminati dall’ampere».

Poi feci il passo logico: io, senza istruzione, senza conoscenze, con alle spalle soltanto una grande fede, fondai la mia religione, i «Testimoni della fisica».

Era difficile diffondere questa religione nel nostro paese. Soprattutto quando raccontai che la Terra gira intorno al Sole, e i compaesani bruciarono subito... un agnellino. Perché c’era l’ennesima festa ortodossa, che richiede per forza dei sacrifici.

Era difficile dimostrare che la Terra gira intorno al Sole. Da una parte, perché la gente faticava a credere, tanto per cominciare, che la Terra fosse rotonda. Ma io, grazie alla fisica, avevo un tavolo storto, e qualsiasi mela ci rotolava sempre giù. Dall’altra, perché quel perfido Sole si muove sempre per il cielo, come se lo facesse apposta!!! Ma io avevo un super argomento: la fede!

E ci credettero. E la vita nel nostro paese si sistemò! Soprattutto quando la gente diventò «testimone della fisica» e smise di credere nella resurrezione dopo la morte. Nel fuoco che senza fiammiferi compare una volta all’anno in un punto ben preciso della Terra. Nel fatto che si può semplicemente uccidere per la fede, fare spedizioni, bruciare e torturare le persone, e soprattutto gli animali, portando loro via la vita, le uova, i piccoli, per una bella tavola a ogni festa religiosa.

Ecco la nostra fede: si sviluppa, non sta ferma come le altre fedi. Ecco, da noi ogni anno esce una nuova sacra scrittura di fisica, con le correzioni. Per esempio, ormai il nucleo è divisibile, e il tempo non scorre uguale per tutti. Anche se questo lo sapevo già da sola, perché quando aspetti qualcosa il tempo scorre lento, non passa mai, e quando mangi un pezzetto di qualcosa di buono il tempo vola velocissimo.

Certo, nel nostro paese ci sono anche altri settari di ogni sorta. Per esempio, ce n’è uno che gira qui intorno a parlare della fede nella matematica. Oh, che fantasioso! Quando comincia a raccontare che ormai si può dividere per zero, che esiste una certa infinità, certi limiti... Ma che fantasioso! Io non ho mai visto una tavoletta di cioccolato infinita, o che una tavoletta si possa dividere per zero all’infinito. Che fantasioso!!!
Se volete, potete conoscerlo qui: https://ritunia.com/tales/mir-ne-takoy-kak-tebe , ma non ve lo consiglio: è un tipo un po’ losco.$tr$ ELSE body_it END,
       dek_it = CASE WHEN COALESCE(dek_it, '') = '' THEN $tr$Non mi servono i fatti, ho la fede.$tr$ ELSE dek_it END,
       title_it = CASE WHEN COALESCE(title_it, '') = '' THEN $tr$Testimone della fisica$tr$ ELSE title_it END
 WHERE slug = 'ya-veryu' AND kind = 'tale';

-- bagpiper (es)
UPDATE battle_cards
   SET effect_es = CASE WHEN COALESCE(effect_es, '') = '' THEN $tr$Zumbido fuerte: durante 2 turnos un enemigo a su alcance golpea 1 más flojo.$tr$ ELSE effect_es END,
       title_es = CASE WHEN COALESCE(title_es, '') = '' THEN $tr$Gaitero de la montaña$tr$ ELSE title_es END,
       abilities = CASE WHEN abilities IS NOT NULL AND jsonb_typeof(abilities::jsonb) = 'array' AND EXISTS (SELECT 1 FROM jsonb_array_elements(abilities::jsonb) WITH ORDINALITY AS e(a, ord) WHERE (e.a->>'id' = 'drone' AND COALESCE(e.a->>'nameEs', '') = '')) THEN (SELECT jsonb_agg(CASE WHEN e.a->>'id' = 'drone' AND COALESCE(e.a->>'nameEs', '') = '' THEN (e.a) || jsonb_build_object('nameEs', $tr$Zumbido$tr$) ELSE (e.a) END ORDER BY e.ord) FROM jsonb_array_elements(abilities::jsonb) WITH ORDINALITY AS e(a, ord))::text ELSE abilities END
 WHERE slug = 'bagpiper';

