   SET effect_de = CASE WHEN COALESCE(effect_de, '') = '' THEN $tr$Brummen: Ein Feind in Reichweite schlägt 2 Züge lang um 1 schwächer.$tr$ ELSE effect_de END,
       title_de = CASE WHEN COALESCE(title_de, '') = '' THEN $tr$Dudelsackpfeifer$tr$ ELSE title_de END,
       abilities = CASE WHEN abilities IS NOT NULL AND jsonb_typeof(abilities::jsonb) = 'array' AND EXISTS (SELECT 1 FROM jsonb_array_elements(abilities::jsonb) WITH ORDINALITY AS e(a, ord) WHERE (e.a->>'id' = 'drone' AND COALESCE(e.a->>'nameDe', '') = '')) THEN (SELECT jsonb_agg(CASE WHEN e.a->>'id' = 'drone' AND COALESCE(e.a->>'nameDe', '') = '' THEN (e.a) || jsonb_build_object('nameDe', $tr$Brummen$tr$) ELSE (e.a) END ORDER BY e.ord) FROM jsonb_array_elements(abilities::jsonb) WITH ORDINALITY AS e(a, ord))::text ELSE abilities END
 WHERE slug = 'bagpiper';

