       title_it = CASE WHEN COALESCE(title_it, '') = '' THEN $tr$Vecchia pastora$tr$ ELSE title_it END,
       abilities = CASE WHEN abilities IS NOT NULL AND jsonb_typeof(abilities::jsonb) = 'array' AND EXISTS (SELECT 1 FROM jsonb_array_elements(abilities::jsonb) WITH ORDINALITY AS e(a, ord) WHERE (e.a->>'id' = 'heal' AND COALESCE(e.a->>'nameIt', '') = '')) THEN (SELECT jsonb_agg(CASE WHEN e.a->>'id' = 'heal' AND COALESCE(e.a->>'nameIt', '') = '' THEN (e.a) || jsonb_build_object('nameIt', $tr$Cura$tr$) ELSE (e.a) END ORDER BY e.ord) FROM jsonb_array_elements(abilities::jsonb) WITH ORDINALITY AS e(a, ord))::text ELSE abilities END
 WHERE slug = 'granny-with-a-sheep';

