-- frames 1 (es)
UPDATE settings
   SET value = jsonb_set(value::jsonb, '{frames}', (SELECT jsonb_agg(CASE WHEN (e.a->>'tier') = '1' AND COALESCE(e.a->>'nameEs', '') = '' THEN e.a || jsonb_build_object('nameEs', $tr$Modesta$tr$) ELSE e.a END ORDER BY e.ord) FROM jsonb_array_elements(value::jsonb->'frames') WITH ORDINALITY AS e(a, ord)))::text
 WHERE key = 'battle_frames'
   AND jsonb_typeof(value::jsonb->'frames') = 'array'
   AND EXISTS (SELECT 1 FROM jsonb_array_elements(value::jsonb->'frames') WITH ORDINALITY AS e(a, ord) WHERE (e.a->>'tier') = '1' AND COALESCE(e.a->>'nameEs', '') = '');

