   SET value = jsonb_set(value::jsonb, '{motions}', (SELECT jsonb_agg(CASE WHEN e.a->>'id' = '8b53c732-860a-47af-9fa3-237d8f60fe3b' AND COALESCE(e.a->>'nameEs', '') = '' THEN e.a || jsonb_build_object('nameEs', $tr$Hacha$tr$) ELSE e.a END ORDER BY e.ord) FROM jsonb_array_elements(value::jsonb->'motions') WITH ORDINALITY AS e(a, ord)))::text
 WHERE key = 'battle_motions'
   AND jsonb_typeof(value::jsonb->'motions') = 'array'
   AND EXISTS (SELECT 1 FROM jsonb_array_elements(value::jsonb->'motions') WITH ORDINALITY AS e(a, ord) WHERE e.a->>'id' = '8b53c732-860a-47af-9fa3-237d8f60fe3b' AND COALESCE(e.a->>'nameEs', '') = '');

