-- copy homeTitle (es)
UPDATE settings
   SET value = (value::jsonb || jsonb_build_object('es', COALESCE(value::jsonb->'es', '{}'::jsonb) || jsonb_build_object('homeTitle', $tr$Muñecas y esculturas de autor hechas a mano$tr$)))::text
 WHERE key = 'copy_overrides'
   AND COALESCE(value::jsonb->'en'->>'homeTitle', '') <> ''
   AND COALESCE(value::jsonb->'es'->>'homeTitle', '') = '';

